DO $R$ BEGIN EXECUTE $Q89$CREATE OR REPLACE FUNCTION public.delete_beat_permanent(p_beat_id text)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_check jsonb;
BEGIN
  v_check := public.can_delete_beat(p_beat_id);
  IF (v_check->>'deletable')::boolean IS NOT TRUE THEN
    RAISE EXCEPTION 'Beat has historical references and cannot be deleted: %', v_check->'reasons';
  END IF;
  DELETE FROM public.beats WHERE beat_id = p_beat_id;
  RETURN jsonb_build_object('status','deleted');
END $$$Q89$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260601084631_d87b450a-004b-4065-90df-97b29bc3ea5f.sql', left($Q89$CREATE OR REPLACE FUNCTION public.delete_beat_permanent(p_beat_id text)
