DO $R$ BEGIN EXECUTE $Q108$CREATE OR REPLACE FUNCTION public.sync_retailers_beat_name()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.beat_name IS DISTINCT FROM OLD.beat_name THEN
    UPDATE public.retailers
       SET beat_name = NEW.beat_name,
           updated_at = now()
     WHERE beat_id = NEW.beat_id
       AND beat_name IS DISTINCT FROM NEW.beat_name;
  END IF;
  RETURN NEW;
END;
