DO $R$ BEGIN EXECUTE $Q394$CREATE POLICY "retailers_update"
ON public.retailers
FOR UPDATE
TO authenticated
USING (
  user_has_permission(auth.uid(), 'module_my_retailers', 'can_edit')
  AND (
    auth.uid() = user_id
    OR user_has_beat_access(auth.uid(), beat_id)
    OR user_has_permission(auth.uid(), 'module_my_retailers', 'can_view_all')
  )
)
WITH CHECK (
  user_has_permission(auth.uid(), 'module_my_retailers', 'can_edit')
  AND (
    auth.uid() = user_id
    OR user_has_beat_access(auth.uid(), beat_id)
    OR user_has_permission(auth.uid(), 'module_my_retailers', 'can_view_all')
  )
)$Q394$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260613041954_db4e3dbe-bd03-4341-bda3-3b3b55079aec.sql', left($Q394$CREATE POLICY "retailers_update"
