DO $R$ BEGIN EXECUTE $Q429$-- 6. RPC: set_company_feature
CREATE OR REPLACE FUNCTION public.set_company_feature(
  p_company_id uuid,
  p_feature_key text,
  p_enabled boolean,
  p_cascade boolean DEFAULT false
)
RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = public
AS $$
DECLARE
  v_feature_id uuid;
  v_old boolean;
  v_dep_id uuid;
BEGIN
