  LIMIT 1;

  RETURN QUERY
  WITH role_override AS (
    SELECT rfc.feature_id, rfc.is_enabled
    FROM public.role_feature_config rfc
    WHERE v_role IS NOT NULL AND rfc.role_id = v_role
  ),
  base AS (
    SELECT
      ff.id AS feature_id,
