DO $R$ BEGIN EXECUTE $Q573$-- 2. Snapshot RPC (safe defaults if related tables missing/empty)
CREATE OR REPLACE FUNCTION public.get_distributor_financial_snapshot(p_distributor_id uuid)
RETURNS TABLE(
  credit_limit numeric,
  outstanding numeric,
  available_credit numeric,
  credit_utilization_pct numeric,
  last_payment_date timestamptz,
  overdue_amount numeric
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_credit_limit numeric := 0;
  v_outstanding numeric := 0;
  v_last_payment timestamptz;
  v_overdue numeric := 0;
BEGIN
  SELECT COALESCE(dpc.credit_limit, 0) INTO v_credit_limit
  FROM public.distributor_payment_config dpc
  WHERE dpc.distributor_id = p_distributor_id;

  v_credit_limit := COALESCE(v_credit_limit, 0);

  RETURN QUERY SELECT
    v_credit_limit,
    v_outstanding,
    GREATEST(v_credit_limit - v_outstanding, 0),
    CASE WHEN v_credit_limit > 0 THEN ROUND((v_outstanding / v_credit_limit) * 100, 2) ELSE 0 END,
    v_last_payment,
    v_overdue;
END;
$$$Q573$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260617104743_fbff7078-e059-4761-8609-731b220591ad.sql', left($Q573$-- 2. Snapshot RPC (safe defaults if related tables missing/empty)
