DO $R$ BEGIN EXECUTE $Q605$-- 3. Admin-only backfill (uses existing has_role helper if present; otherwise restrict by service_role only)
CREATE OR REPLACE FUNCTION public.backfill_retailer_payment_allocations()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_retailer RECORD;
  v_collection RECORD;
  v_processed int := 0;
  v_skipped int := 0;
BEGIN
  -- Caller must be admin
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins may run backfill';
  END IF;

  FOR v_collection IN
    SELECT c.id, c.retailer_id, c.amount
    FROM public.retailer_payment_collections c
    WHERE NOT EXISTS (
      SELECT 1 FROM public.retailer_payment_allocations a WHERE a.collection_id = c.id
    )
    ORDER BY c.created_at ASC
  LOOP
    BEGIN
      PERFORM public.apply_retailer_payment_fifo(
        v_collection.retailer_id, v_collection.amount, v_collection.id
      );
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('processed', v_processed, 'skipped', v_skipped);
END;
$$$Q605$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260618090638_b4357922-4b59-4ac3-b59a-fe21ba6eebca.sql', left($Q605$-- 3. Admin-only backfill (uses existing has_role helper if present; otherwise restrict by service_role only)
CREATE OR REPLACE FUNCTION public.backfill_retailer_payment_allocations()
RETURNS jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_retailer RECORD;
  v_collection RECORD;
  v_processed int := 0;
  v_skipped int := 0;
BEGIN
  -- Caller must be admin
  IF NOT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id = auth.uid() AND role = 'admin'
  ) THEN
    RAISE EXCEPTION 'Only admins may run backfill';
  END IF;

  FOR v_collection IN
    SELECT c.id, c.retailer_id, c.amount
    FROM public.retailer_payment_collections c
    WHERE NOT EXISTS (
      SELECT 1 FROM public.retailer_payment_allocations a WHERE a.collection_id = c.id
    )
    ORDER BY c.created_at ASC
  LOOP
    BEGIN
      PERFORM public.apply_retailer_payment_fifo(
        v_collection.retailer_id, v_collection.amount, v_collection.id
      );
      v_processed := v_processed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_skipped := v_skipped + 1;
    END;
  END LOOP;

  RETURN jsonb_build_object('processed', v_processed, 'skipped', v_skipped);
END;
