DO $R$ BEGIN EXECUTE $Q611$-- 2. Keep retailers.beat_name in sync with beats.beat_name on insert/update of beat_id
CREATE OR REPLACE FUNCTION public.sync_retailer_beat_name()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  resolved_name text;
BEGIN
  IF NEW.beat_id IS NULL OR NEW.beat_id = '' OR NEW.beat_id = 'unassigned' THEN
    RETURN NEW;
  END IF;

  -- If beat_name is missing or looks like a beat-id slug, resolve it from beats
  IF NEW.beat_name IS NULL
     OR NEW.beat_name = NEW.beat_id
     OR NEW.beat_name ~ '^beat_[0-9]+_[a-z0-9]+$'
     OR (TG_OP = 'UPDATE' AND NEW.beat_id IS DISTINCT FROM OLD.beat_id)
  THEN
    SELECT b.beat_name INTO resolved_name
    FROM public.beats b
    WHERE b.beat_id = NEW.beat_id
    LIMIT 1;

    IF resolved_name IS NOT NULL THEN
      NEW.beat_name := resolved_name;
    END IF;
  END IF;

  RETURN NEW;
END;
$$$Q611$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260618092858_0a22ba92-5f0e-4187-887d-499026afb128.sql', left($Q611$-- 2. Keep retailers.beat_name in sync with beats.beat_name on insert/update of beat_id
