DO $R$ BEGIN EXECUTE $Q653$CREATE OR REPLACE FUNCTION public.generate_primary_invoice_number()
RETURNS text
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  RETURN 'PINV-' || to_char(now(), 'YYMM') || '-' ||
         lpad(nextval('public.primary_invoice_seq')::text, 5, '0');
END;
