DO $R$ BEGIN EXECUTE $Q662$-- 1) Authoritative recompute helper
CREATE OR REPLACE FUNCTION public.recompute_retailer_pending(p_retailer_id uuid)
RETURNS numeric
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_new_pending numeric := 0;
BEGIN
  IF p_retailer_id IS NULL THEN
    RETURN 0;
  END IF;

  SELECT COALESCE(SUM(GREATEST(COALESCE(credit_pending_amount, 0), 0)), 0)
    INTO v_new_pending
  FROM public.orders
  WHERE retailer_id = p_retailer_id
    AND COALESCE(status, '') <> 'cancelled'
    AND is_credit_order = true;

  UPDATE public.retailers
     SET pending_amount = v_new_pending,
         updated_at = now()
   WHERE id = p_retailer_id;

  RETURN v_new_pending;
END;
$$$Q662$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260622121540_6d4cbb52-87ba-4482-9898-ee77443f2bc8.sql', left($Q662$-- 1) Authoritative recompute helper
