DO $R$ BEGIN EXECUTE $Q708$CREATE OR REPLACE FUNCTION public.sync_primary_packing_list_on_delivery()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_pl_id uuid := NEW.packing_list_id;
  v_remaining int;
BEGIN
  IF v_pl_id IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.status IS DISTINCT FROM 'delivered' THEN
    RETURN NEW;
  END IF;

  SELECT count(*) INTO v_remaining
  FROM public.primary_orders
  WHERE packing_list_id = v_pl_id
    AND status <> 'delivered';

  IF v_remaining = 0 THEN
    UPDATE public.packing_lists
       SET status = 'delivered',
           delivered_at = now()
     WHERE id = v_pl_id
       AND status = 'dispatched';
  END IF;

  RETURN NEW;
END;
