-- 5. Challan number generator
-- =====================================================
CREATE OR REPLACE FUNCTION public.generate_delivery_challan_number(p_date date)
RETURNS text LANGUAGE plpgsql AS $$
DECLARE next_num integer;
BEGIN
  SELECT COALESCE(MAX(
    CASE WHEN challan_number ~ '^DC-[0-9]{8}-[0-9]+$'
      THEN CAST(SPLIT_PART(challan_number,'-',3) AS integer) ELSE 0 END
  ),0) + 1 INTO next_num
  FROM public.delivery_challans
  WHERE challan_date = p_date;
  RETURN 'DC-' || to_char(p_date,'YYYYMMDD') || '-' || lpad(next_num::text,4,'0');
END $$$Q779$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260625101836_b532b14c-9906-4a0e-8f64-11e91f3e476c.sql', left($Q779$-- =====================================================
