DO $R$ BEGIN EXECUTE $Q811$-- 2) PRODUCTS TRIGGER: keep tax_master_id <-> gst_percentage in lockstep
CREATE OR REPLACE FUNCTION public.sync_product_tax_link()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_rate NUMERIC;
  v_tax_id UUID;
BEGIN
  IF NEW.tax_master_id IS NOT NULL THEN
    SELECT total_rate INTO v_rate
    FROM public.tax_masters
    WHERE id = NEW.tax_master_id;
    IF v_rate IS NOT NULL THEN
      NEW.gst_percentage := v_rate;
    END IF;
  ELSIF NEW.gst_percentage IS NOT NULL THEN
    SELECT id INTO v_tax_id
    FROM public.tax_masters
    WHERE is_active = true
      AND total_rate = NEW.gst_percentage
    ORDER BY created_at
    LIMIT 1;
    IF v_tax_id IS NOT NULL THEN
      NEW.tax_master_id := v_tax_id;
    END IF;
  END IF;
  RETURN NEW;
END;
$$$Q811$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260629044420_63e35cfe-7457-4819-8374-90365fc09e14.sql', left($Q811$-- 2) PRODUCTS TRIGGER: keep tax_master_id <-> gst_percentage in lockstep
