DO $R$ BEGIN EXECUTE $Q814$-- 3) TAX MASTER TRIGGER: propagate rate changes to linked products
CREATE OR REPLACE FUNCTION public.propagate_tax_master_rate()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
BEGIN
  IF NEW.total_rate IS DISTINCT FROM OLD.total_rate THEN
    UPDATE public.products
    SET gst_percentage = NEW.total_rate
    WHERE tax_master_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$$Q814$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260629044420_63e35cfe-7457-4819-8374-90365fc09e14.sql', left($Q814$-- 3) TAX MASTER TRIGGER: propagate rate changes to linked products
