DO $R$ BEGIN EXECUTE $Q827$-- 4) Extend tax-master rate propagation to also update linked variants
CREATE OR REPLACE FUNCTION public.propagate_tax_master_rate()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $$
BEGIN
  IF NEW.total_rate IS DISTINCT FROM OLD.total_rate THEN
    UPDATE public.products
    SET gst_percentage = NEW.total_rate
    WHERE tax_master_id = NEW.id;

    UPDATE public.product_variants
    SET gst_percentage = NEW.total_rate
    WHERE tax_master_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$$Q827$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260629121111_27d857f8-f75e-447b-b1ff-a2351a4d3358.sql', left($Q827$-- 4) Extend tax-master rate propagation to also update linked variants
