DO $R$ BEGIN EXECUTE $Q1065$-- 1. can_backdate_order
CREATE OR REPLACE FUNCTION public.can_backdate_order(p_date date)
RETURNS boolean
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_enabled  boolean;
  v_max_days integer;
BEGIN
  SELECT backdate_enabled, backdate_max_days
    INTO v_enabled, v_max_days
    FROM public.operations_config
   WHERE id = 1;

  IF NOT COALESCE(v_enabled, false) THEN
    RETURN false;
  END IF;

  IF NOT public.user_has_permission(auth.uid(), 'order_backdate', 'can_create') THEN
    RETURN false;
  END IF;

  IF p_date > CURRENT_DATE THEN
    RETURN false;
  END IF;

  IF p_date >= (CURRENT_DATE - (COALESCE(v_max_days, 0) || ' days')::interval)::date THEN
    RETURN true;
  END IF;

  RETURN EXISTS (
    SELECT 1
      FROM public.order_backdate_date_grants
     WHERE user_id = auth.uid()
       AND order_date = p_date
  );
END;
$$$Q1065$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260703094129_4c96eb06-84b1-494d-8a01-eaa2b8ef342b.sql', left($Q1065$-- 1. can_backdate_order
