DO $R$ BEGIN EXECUTE $Q1077$-- 3. request_backdate function
CREATE OR REPLACE FUNCTION public.request_backdate(p_date date, p_reason text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_enabled boolean;
  v_req_id uuid;
  v_approval_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT backdate_enabled INTO v_enabled FROM public.operations_config WHERE id = 1;
  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'Backdated orders are disabled';
  END IF;

  IF NOT public.user_has_permission(v_uid,'order_backdate','can_create') THEN
    RAISE EXCEPTION 'You do not have permission to request a backdated order';
  END IF;

  INSERT INTO public.order_backdate_requests (user_id, order_date, reason)
  VALUES (v_uid, p_date, p_reason)
  RETURNING id INTO v_req_id;

  v_approval_id := public.create_approval_request('order_backdate', v_req_id, v_uid);

  IF v_approval_id IS NULL THEN
    RAISE EXCEPTION 'No approver could be resolved for this backdate request';
  END IF;

  UPDATE public.order_backdate_requests
     SET approval_request_id = v_approval_id
   WHERE id = v_req_id;

  RETURN v_req_id;
END; $$$Q1077$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260703104721_41771574-36b5-4135-ac69-a4cfcd5f6069.sql', left($Q1077$-- 3. request_backdate function
CREATE OR REPLACE FUNCTION public.request_backdate(p_date date, p_reason text)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_uid uuid := auth.uid();
  v_enabled boolean;
  v_req_id uuid;
  v_approval_id uuid;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'Not authenticated';
  END IF;

  SELECT backdate_enabled INTO v_enabled FROM public.operations_config WHERE id = 1;
  IF NOT COALESCE(v_enabled, false) THEN
    RAISE EXCEPTION 'Backdated orders are disabled';
  END IF;

  IF NOT public.user_has_permission(v_uid,'order_backdate','can_create') THEN
    RAISE EXCEPTION 'You do not have permission to request a backdated order';
  END IF;

  INSERT INTO public.order_backdate_requests (user_id, order_date, reason)
  VALUES (v_uid, p_date, p_reason)
  RETURNING id INTO v_req_id;

  v_approval_id := public.create_approval_request('order_backdate', v_req_id, v_uid);

  IF v_approval_id IS NULL THEN
    RAISE EXCEPTION 'No approver could be resolved for this backdate request';
  END IF;

  UPDATE public.order_backdate_requests
     SET approval_request_id = v_approval_id
   WHERE id = v_req_id;

  RETURN v_req_id;
END; $$$Q1077$,400), SQLERRM, SQLSTATE); END $R$;
