DO $R$ BEGIN EXECUTE $Q1079$-- 4. Trigger on approval_requests for order_backdate finalisation
CREATE OR REPLACE FUNCTION public.tg_order_backdate_approval_complete()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_req public.order_backdate_requests%ROWTYPE;
BEGIN
  IF NEW.entity_type <> 'order_backdate' THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'approved' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    SELECT * INTO v_req FROM public.order_backdate_requests WHERE id = NEW.entity_id FOR UPDATE;
    IF FOUND THEN
      INSERT INTO public.order_backdate_date_grants (user_id, order_date, reason)
      VALUES (v_req.user_id, v_req.order_date, v_req.reason)
      ON CONFLICT DO NOTHING;

      UPDATE public.order_backdate_requests SET status = 'approved' WHERE id = NEW.entity_id;
    END IF;
  ELSIF NEW.status = 'rejected' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    UPDATE public.order_backdate_requests SET status = 'rejected' WHERE id = NEW.entity_id;
  END IF;

  RETURN NEW;
END; $$$Q1079$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260703104721_41771574-36b5-4135-ac69-a4cfcd5f6069.sql', left($Q1079$-- 4. Trigger on approval_requests for order_backdate finalisation
CREATE OR REPLACE FUNCTION public.tg_order_backdate_approval_complete()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_req public.order_backdate_requests%ROWTYPE;
BEGIN
  IF NEW.entity_type <> 'order_backdate' THEN
    RETURN NEW;
  END IF;

  IF NEW.status = 'approved' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    SELECT * INTO v_req FROM public.order_backdate_requests WHERE id = NEW.entity_id FOR UPDATE;
    IF FOUND THEN
      INSERT INTO public.order_backdate_date_grants (user_id, order_date, reason)
      VALUES (v_req.user_id, v_req.order_date, v_req.reason)
      ON CONFLICT DO NOTHING;

      UPDATE public.order_backdate_requests SET status = 'approved' WHERE id = NEW.entity_id;
    END IF;
  ELSIF NEW.status = 'rejected' AND (OLD.status IS DISTINCT FROM NEW.status) THEN
    UPDATE public.order_backdate_requests SET status = 'rejected' WHERE id = NEW.entity_id;
  END IF;

  RETURN NEW;
END; $$$Q1079$,400), SQLERRM, SQLSTATE); END $R$;
