DO $R$ BEGIN EXECUTE $Q1086$CREATE POLICY retailers_select ON public.retailers
FOR SELECT
USING (
  user_has_permission(auth.uid(), 'module_my_retailers', 'can_read')
  AND (
    auth.uid() = user_id
    OR user_has_beat_access(auth.uid(), beat_id)
    OR EXISTS (
      SELECT 1
        FROM daily_beat_plans dbp
       WHERE dbp.beat_id = retailers.beat_id
         AND dbp.assigned_user_id = auth.uid()
         AND dbp.status = 'active'
    )
    OR is_subordinate_of(auth.uid(), user_id)
    OR user_has_permission(auth.uid(), 'module_my_retailers', 'can_view_all')
    OR public.retailer_in_user_oob_scope(id)
  )
)$Q1086$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260706042245_e2db668c-cd08-4b23-87fd-d258f4d4ed78.sql', left($Q1086$CREATE POLICY retailers_select ON public.retailers
