DO $R$ BEGIN EXECUTE $Q1129$-- 2. next_free_day
CREATE OR REPLACE FUNCTION public.next_free_day(p_user uuid, p_from date)
RETURNS date
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_end date := (date_trunc('month', p_from) + interval '1 month - 1 day')::date;
  d date := p_from + 1;
BEGIN
  WHILE d <= v_end LOOP
    IF NOT EXISTS (
      SELECT 1 FROM leave_applications
      WHERE user_id = p_user AND status = 'approved'
        AND d BETWEEN start_date AND end_date
    ) AND NOT EXISTS (
      SELECT 1 FROM visits WHERE user_id = p_user AND planned_date = d
    ) THEN
      RETURN d;
    END IF;
    d := d + 1;
  END LOOP;
  RETURN NULL;
END;
$$$Q1129$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260706072720_67d1ff43-4e4d-4487-964c-4674e15fe21d.sql', left($Q1129$-- 2. next_free_day
