DO $R$ BEGIN EXECUTE $Q1133$-- 4. reschedule_missed_day
CREATE OR REPLACE FUNCTION public.reschedule_missed_day(
  p_user uuid,
  p_from_date date,
  p_to_date date DEFAULT NULL
)
RETURNS TABLE(moved integer, to_date date)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_to date;
  v_count integer;
BEGIN
  IF NOT (p_user = auth.uid() OR public.is_subordinate_of(auth.uid(), p_user)) THEN
    RETURN;
  END IF;

  v_to := COALESCE(p_to_date, public.next_free_day(p_user, p_from_date));
  IF v_to IS NULL THEN
    RAISE EXCEPTION 'No free day available this month';
  END IF;

  WITH updated AS (
    UPDATE visits v
    SET planned_date = v_to,
        status = 'planned',
        cancel_source = NULL,
        is_rescheduled = true,
        rescheduled_from_date = p_from_date,
        updated_at = now()
    WHERE v.user_id = p_user
      AND v.planned_date = p_from_date
      AND v.status IN ('planned','cancelled')
      AND NOT EXISTS (
        SELECT 1 FROM visits v2
        WHERE v2.user_id = p_user
          AND v2.retailer_id = v.retailer_id
          AND v2.planned_date = v_to
          AND v2.status = 'planned'
      )
    RETURNING 1
  )
  SELECT COUNT(*)::integer INTO v_count FROM updated;

  moved := v_count;
  to_date := v_to;
  RETURN NEXT;
END;
$$$Q1133$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260706072720_67d1ff43-4e4d-4487-964c-4674e15fe21d.sql', left($Q1133$-- 4. reschedule_missed_day
