  SELECT EXISTS(SELECT 1 FROM user_roles WHERE user_id=v_uid AND role='admin') INTO v_is_admin;
  IF NOT v_is_admin THEN
    SELECT COALESCE(sp.is_system,false) INTO v_is_admin
