DO $R$ BEGIN EXECUTE $Q1216$-- Function invoked by AFTER INSERT trigger on notifications: fires an async
-- HTTP POST to the send-push edge function via pg_net. Skips when the row's
-- actor equals the recipient (self-suppression) or when user_id is null.
CREATE OR REPLACE FUNCTION public.dispatch_push_for_notification()
RETURNS TRIGGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_actor text;
  v_route text;
  v_url text;
  v_secret text;
  v_body jsonb;
BEGIN
  IF NEW.user_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_actor := NEW.metadata->>'actor_id';
  IF v_actor IS NOT NULL AND v_actor = NEW.user_id::text THEN
    RETURN NEW;
  END IF;

  -- Config read from database settings (set via ALTER DATABASE ... SET app.*)
  v_url := current_setting('app.push_function_url', true);
  v_secret := current_setting('app.push_trigger_secret', true);

  IF v_url IS NULL OR v_url = '' THEN
    RETURN NEW; -- not configured yet
  END IF;

  v_route := NEW.metadata->>'route';

  v_body := jsonb_build_object(
    'user_id', NEW.user_id,
    'title', NEW.title,
    'body', NEW.message,
    'data', jsonb_build_object(
      'route', v_route,
      'notification_id', NEW.id,
      'type', NEW.type,
      'related_table', NEW.related_table,
      'related_id', NEW.related_id
    )
  );

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object(
      'Content-Type', 'application/json',
      'x-push-secret', COALESCE(v_secret, '')
    ),
    body := v_body,
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never break the insert if push dispatch fails
  RETURN NEW;
END;
$$$Q1216$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260710052059_ab1b579a-67b2-4d62-8ae3-4001dc36a6b2.sql', left($Q1216$-- Function invoked by AFTER INSERT trigger on notifications: fires an async
