DO $R$ BEGIN EXECUTE $Q1291$-- Prevent destructive deletion of security profiles.
-- A profile may be HARD-deleted ONLY when it is non-system AND has zero users assigned.
-- Otherwise it must be deactivated (is_active=false). Enforced at DB level so no UI or
-- direct-SQL path can silently orphan users (as happened to the System Administrator profile).

ALTER TABLE public.security_profiles
  ADD COLUMN IF NOT EXISTS is_active boolean NOT NULL DEFAULT true$Q1291$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260714093000_guard_security_profile_delete.sql', left($Q1291$-- Prevent destructive deletion of security profiles.
