DO $R$ BEGIN EXECUTE $Q1393$-- Auto attribution
CREATE OR REPLACE FUNCTION public.orders_autoattribute_influencer()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE v_inf uuid; v_cnt int;
BEGIN
  IF NEW.influencer_id IS NULL AND NEW.retailer_id IS NOT NULL THEN
    SELECT count(*), min(influencer_id) INTO v_cnt, v_inf
    FROM public.influencer_retailer_map
    WHERE retailer_id = NEW.retailer_id AND active;
    IF v_cnt = 1 THEN NEW.influencer_id := v_inf; END IF;
  END IF;
  RETURN NEW;
END; $$$Q1393$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260718074429_22e6e797-8b6b-4e7b-a4dc-eaa76fe0edaa.sql', left($Q1393$-- Auto attribution
