DO $R$ BEGIN EXECUTE $Q1458$-- 1. Fix get_attendance_report: lowercase statuses (present/leave/half_day_leave/regularized)
--    and derive "absent" via LEFT JOIN of active-employee roster to attendance rows.
CREATE OR REPLACE FUNCTION public.get_attendance_report(
  p_layout text, p_rows text, p_columns text, p_values text[], p_filters jsonb
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_user_ids UUID[];
  v_rec JSONB;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true
          AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          d.d          AS date,
          r.user_id,
          r.team_member,
          COALESCE(a.status, 'absent') AS status,
          a.total_hours AS hours
        FROM days d
        CROSS JOIN roster r
        LEFT JOIN public.attendance a
               ON a.user_id = r.user_id AND a.date = d.d
        ORDER BY d.d DESC, r.team_member
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;

  ELSIF p_layout = 'grouped' THEN
    IF p_rows = 'team_member' THEN
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
          FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        )
        SELECT to_jsonb(t) FROM (
          SELECT
            r.team_member,
            ROUND(AVG(a.total_hours)::numeric, 2) AS hours,
            COUNT(*) FILTER (WHERE a.status = 'present')        AS present,
            COUNT(*) FILTER (WHERE a.status = 'leave')          AS on_leave,
            COUNT(*) FILTER (WHERE a.status = 'half_day_leave') AS half_day,
            COUNT(*) FILTER (WHERE a.status = 'regularized')    AS regularized,
            COUNT(*) FILTER (WHERE a.id IS NULL)                AS absent,
            COUNT(*)                                            AS total_days
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
          GROUP BY r.team_member
          ORDER BY r.team_member
          LIMIT 2000
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;

    ELSIF p_rows = 'date' THEN
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        )
        SELECT to_jsonb(t) FROM (
          SELECT
            d.d AS date,
            ROUND(AVG(a.total_hours)::numeric, 2) AS hours,
            COUNT(*) FILTER (WHERE a.status = 'present')        AS present,
            COUNT(*) FILTER (WHERE a.status = 'leave')          AS on_leave,
            COUNT(*) FILTER (WHERE a.status = 'half_day_leave') AS half_day,
            COUNT(*) FILTER (WHERE a.status = 'regularized')    AS regularized,
            COUNT(*) FILTER (WHERE a.id IS NULL)                AS absent
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
          GROUP BY d.d
          ORDER BY d.d DESC
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;

    ELSE  -- rows = status
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        ),
        merged AS (
          SELECT COALESCE(a.status, 'absent') AS status, a.total_hours
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
        )
        SELECT to_jsonb(t) FROM (
          SELECT status, COUNT(*) AS count, ROUND(AVG(total_hours)::numeric, 2) AS hours
          FROM merged
          GROUP BY status
          ORDER BY status
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;
    END IF;

  ELSIF p_layout = 'matrix' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true
          AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          r.team_member,
          jsonb_object_agg(
            d.d::text,
            CASE WHEN a.status = 'present' THEN 1 ELSE 0 END
          ) AS by_date
        FROM days d
        CROSS JOIN roster r
        LEFT JOIN public.attendance a
               ON a.user_id = r.user_id AND a.date = d.d
        GROUP BY r.team_member
        ORDER BY r.team_member
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  END IF;

  RETURN;
END;
$function$$Q1458$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260720110846_78431d3c-b501-4c1b-a6cc-5e26e8ec3f79.sql', left($Q1458$-- 1. Fix get_attendance_report: lowercase statuses (present/leave/half_day_leave/regularized)
--    and derive "absent" via LEFT JOIN of active-employee roster to attendance rows.
CREATE OR REPLACE FUNCTION public.get_attendance_report(
  p_layout text, p_rows text, p_columns text, p_values text[], p_filters jsonb
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_user_ids UUID[];
  v_rec JSONB;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true
          AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          d.d          AS date,
          r.user_id,
          r.team_member,
          COALESCE(a.status, 'absent') AS status,
          a.total_hours AS hours
        FROM days d
        CROSS JOIN roster r
        LEFT JOIN public.attendance a
               ON a.user_id = r.user_id AND a.date = d.d
        ORDER BY d.d DESC, r.team_member
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;

  ELSIF p_layout = 'grouped' THEN
    IF p_rows = 'team_member' THEN
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
          FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        )
        SELECT to_jsonb(t) FROM (
          SELECT
            r.team_member,
            ROUND(AVG(a.total_hours)::numeric, 2) AS hours,
            COUNT(*) FILTER (WHERE a.status = 'present')        AS present,
            COUNT(*) FILTER (WHERE a.status = 'leave')          AS on_leave,
            COUNT(*) FILTER (WHERE a.status = 'half_day_leave') AS half_day,
            COUNT(*) FILTER (WHERE a.status = 'regularized')    AS regularized,
            COUNT(*) FILTER (WHERE a.id IS NULL)                AS absent,
            COUNT(*)                                            AS total_days
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
          GROUP BY r.team_member
          ORDER BY r.team_member
          LIMIT 2000
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;

    ELSIF p_rows = 'date' THEN
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        )
        SELECT to_jsonb(t) FROM (
          SELECT
            d.d AS date,
            ROUND(AVG(a.total_hours)::numeric, 2) AS hours,
            COUNT(*) FILTER (WHERE a.status = 'present')        AS present,
            COUNT(*) FILTER (WHERE a.status = 'leave')          AS on_leave,
            COUNT(*) FILTER (WHERE a.status = 'half_day_leave') AS half_day,
            COUNT(*) FILTER (WHERE a.status = 'regularized')    AS regularized,
            COUNT(*) FILTER (WHERE a.id IS NULL)                AS absent
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
          GROUP BY d.d
          ORDER BY d.d DESC
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;

    ELSE  -- rows = status
      FOR v_rec IN
        WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
        roster AS (
          SELECT id AS user_id FROM public.profiles
          WHERE is_active = true
            AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
        ),
        merged AS (
          SELECT COALESCE(a.status, 'absent') AS status, a.total_hours
          FROM days d
          CROSS JOIN roster r
          LEFT JOIN public.attendance a
                 ON a.user_id = r.user_id AND a.date = d.d
        )
        SELECT to_jsonb(t) FROM (
          SELECT status, COUNT(*) AS count, ROUND(AVG(total_hours)::numeric, 2) AS hours
          FROM merged
          GROUP BY status
          ORDER BY status
        ) t
      LOOP RETURN NEXT v_rec; END LOOP;
    END IF;

  ELSIF p_layout = 'matrix' THEN
    FOR v_rec IN
      WITH days AS (SELECT generate_series(v_date_from, v_date_to, '1 day')::date AS d),
      roster AS (
        SELECT id AS user_id, COALESCE(full_name, username, 'Unknown') AS team_member
        FROM public.profiles
        WHERE is_active = true
          AND (v_user_ids IS NULL OR id = ANY(v_user_ids))
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          r.team_member,
          jsonb_object_agg(
            d.d::text,
            CASE WHEN a.status = 'present' THEN 1 ELSE 0 END
          ) AS by_date
        FROM days d
        CROSS JOIN roster r
        LEFT JOIN public.attendance a
               ON a.user_id = r.user_id AND a.date = d.d
        GROUP BY r.team_member
        ORDER BY r.team_member
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
  END IF;

  RETURN;
END;
