      enriched AS (
        SELECT
          CASE v_row_key
            WHEN 'date' THEN date::text
            WHEN 'status' THEN status
            WHEN 'beat' THEN COALESCE(beat_raw, 'No beat')
            WHEN 'check_in_time' THEN COALESCE(check_in_time::text, '—')
            WHEN 'check_out_time' THEN COALESCE(check_out_time::text, '—')
            ELSE team_member
          END AS row_val,
          CASE v_col_key
            WHEN 'date' THEN date::text
            WHEN 'status' THEN status
            WHEN 'beat' THEN COALESCE(beat_raw, 'No beat')
            WHEN 'check_in_time' THEN COALESCE(check_in_time::text, '—')
            WHEN 'check_out_time' THEN COALESCE(check_out_time::text, '—')
            ELSE team_member
