DO $R$ BEGIN EXECUTE $Q1520$CREATE OR REPLACE FUNCTION public.create_report_subscription(p_definition jsonb, p_subscription jsonb)
RETURNS uuid
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_def_id UUID;
  v_sub_id UUID;
  v_uid UUID := auth.uid();
BEGIN
  IF NOT public.is_admin_or_manager() THEN
    RAISE EXCEPTION 'Only admins/managers can create report subscriptions';
  END IF;

  INSERT INTO public.report_definitions (name, dataset_key, layout, config, created_by)
  VALUES (
    p_definition->>'name',
