DO $R$ BEGIN EXECUTE $Q1565$CREATE OR REPLACE FUNCTION public.set_notification_read_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.is_read = true AND (OLD.is_read IS DISTINCT FROM true) AND NEW.read_at IS NULL THEN
    NEW.read_at = now();
  END IF;
  IF NEW.is_read = false THEN
    NEW.read_at = NULL;
  END IF;
  RETURN NEW;
END;
$$$Q1565$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260730050348_972f4266-68cb-43fe-8c7c-4c8ca01937da.sql', left($Q1565$CREATE OR REPLACE FUNCTION public.set_notification_read_at()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.is_read = true AND (OLD.is_read IS DISTINCT FROM true) AND NEW.read_at IS NULL THEN
    NEW.read_at = now();
  END IF;
  IF NEW.is_read = false THEN
    NEW.read_at = NULL;
  END IF;
  RETURN NEW;
END;
$$$Q1565$,400), SQLERRM, SQLSTATE); END $R$;
