DO $R$ BEGIN EXECUTE $Q1670$CREATE OR REPLACE FUNCTION public.gam_on_retailer_verified()
RETURNS trigger
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_user uuid;
BEGIN
  IF COALESCE(NEW.verified, false) = true AND COALESCE(OLD.verified, false) = false THEN
    v_user := COALESCE(NEW.owner_id, NEW.user_id, NEW.created_by);
    IF v_user IS NOT NULL THEN
      BEGIN
        PERFORM public.gam_award_event(
          v_user,
          'retailer_verified',
          'retailer',
          NEW.id,
          NEW.id,
          jsonb_build_object(
            'verification_score', NEW.verification_score,
            'verification_method', NEW.verification_method
          ),
          NULL
        );
      EXCEPTION WHEN others THEN NULL;
      END;
    END IF;
  END IF;
  RETURN NEW;
END;
$$$Q1670$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260730102315_60583c1d-97a9-497e-b915-1bb0f00d21bf.sql', left($Q1670$CREATE OR REPLACE FUNCTION public.gam_on_retailer_verified()
