DO $R$ BEGIN EXECUTE $Q1696$-- total_hours was left NULL on 55 rows that have both timestamps, because it is
-- only set by the client on checkout. Compute it in the database instead, so it is
-- correct no matter which path writes the row (app, regularisation, admin edit).

CREATE OR REPLACE FUNCTION public.tg_attendance_compute_hours()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = public
AS $$
BEGIN
  IF NEW.check_in_time IS NOT NULL AND NEW.check_out_time IS NOT NULL THEN
    IF NEW.check_out_time > NEW.check_in_time THEN
      NEW.total_hours := round(
        (EXTRACT(EPOCH FROM (NEW.check_out_time - NEW.check_in_time)) / 3600.0)::numeric, 2);
    ELSE
      -- check-out at or before check-in is a data error (clock skew / bad edit).
      -- Leave NULL rather than storing a negative or fake zero.
      NEW.total_hours := NULL;
    END IF;
  END IF;
  RETURN NEW;
END;
$$$Q1696$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260804051027_attendance_total_hours_autocompute.sql', left($Q1696$-- total_hours was left NULL on 55 rows that have both timestamps, because it is
-- only set by the client on checkout. Compute it in the database instead, so it is
-- correct no matter which path writes the row (app, regularisation, admin edit).

