DO $R$ BEGIN EXECUTE $Q1722$-- get_sales_report: allow the GROUPED layout to group by more than one dimension.
--
-- p_rows is a single text key, so a report configured with
-- rows: ["team_member","order_date"] silently dropped order_date before the
-- query ran — in the builder preview and the delivered file alike.
--
-- Adds p_row_keys text[] with a DEFAULT so every existing 5-argument call still
-- resolves. Backward compatible by design:
--   * p_row_keys omitted/NULL -> legacy behaviour, one dimension aliased "grp"
--   * p_row_keys provided     -> one column per dimension, named after the key
-- TABULAR and MATRIX branches are unchanged.

DROP FUNCTION IF EXISTS public.get_sales_report(text, text, text, text[], jsonb)$Q1722$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260805090342_sales_report_multi_dimension_grouping.sql', left($Q1722$-- get_sales_report: allow the GROUPED layout to group by more than one dimension.
--
-- p_rows is a single text key, so a report configured with
-- rows: ["team_member","order_date"] silently dropped order_date before the
-- query ran — in the builder preview and the delivered file alike.
--
-- Adds p_row_keys text[] with a DEFAULT so every existing 5-argument call still
-- resolves. Backward compatible by design:
--   * p_row_keys omitted/NULL -> legacy behaviour, one dimension aliased "grp"
--   * p_row_keys provided     -> one column per dimension, named after the key
-- TABULAR and MATRIX branches are unchanged.

DROP FUNCTION IF EXISTS public.get_sales_report(text, text, text, text[], jsonb)$Q1722$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1723$CREATE OR REPLACE FUNCTION public.get_sales_report(
  p_layout   text,
  p_rows     text,
  p_columns  text,
  p_values   text[],
  p_filters  jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from     DATE  := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to       DATE  := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user    UUID  := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_distributor   UUID  := NULLIF(p_filters->>'distributor_id','')::UUID;
  v_user_ids      UUID[];
  v_row_key       text  := COALESCE(NULLIF(p_rows,''), 'team_member');
