DO $R$ BEGIN EXECUTE $Q1733$-- Fix: the universe branch selected pre-aggregated CTE columns alongside a
-- GROUP BY, which Postgres rejects. Wrap them in aggregates so the outer query
-- collapses correctly when several base rows share a dimension value.
CREATE OR REPLACE FUNCTION public.get_sales_report(
  p_layout   text,
  p_rows     text,
  p_columns  text,
  p_values   text[],
  p_filters  jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from     DATE  := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to       DATE  := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user    UUID  := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_distributor   UUID  := NULLIF(p_filters->>'distributor_id','')::UUID;
  v_user_ids      UUID[];
  v_row_key       text  := COALESCE(NULLIF(p_rows,''), 'team_member');
  v_col_key       text  := COALESCE(NULLIF(p_columns,''), 'team_member');
  v_val_key       text  := COALESCE(p_values[1], 'quantity');
  v_row_sql       text;
  v_col_sql       text;
  v_val_sql       text;
  v_sql           text;
  v_rec           JSONB;
  v_dims          text[];
  v_aliases       text[];
  v_dim_sql       text := '';
  v_group_sql     text := '';
  v_i             int;
  v_by_day        boolean;
  v_universe      boolean;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt
        FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY retailer_id
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          o.order_date::date                               AS order_date,
          COALESCE(p.full_name, p.username, 'Unknown')     AS team_member,
          COALESCE(o.beat_name_snapshot, b.beat_name)      AS beat,
          o.retailer_name                                  AS retailer,
          o.distributor_name                               AS distributor,
          oi.product_name                                  AS product,
          oi.category                                      AS category,
          oi.uom_code                                      AS uom,
          o.status                                         AS status,
          COALESCE(oi.quantity,0)::numeric                 AS quantity,
          COALESCE(oi.rate,0)::numeric(14,2)               AS rate,
          COALESCE(oi.quantity * oi.rate,0)::numeric(14,2) AS revenue,
          CASE WHEN fo.first_dt = o.order_date::date
                AND fo.first_dt BETWEEN v_date_from AND v_date_to
               THEN 1 ELSE 0 END                           AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR o.distributor_id = v_distributor)
        ORDER BY o.order_date DESC, o.created_at DESC
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_layout = 'matrix' THEN
    v_row_sql := CASE v_row_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_col_sql := CASE v_col_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_val_sql := CASE v_val_key
      WHEN 'revenue' THEN 'COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2)'
      WHEN 'rate' THEN 'COALESCE(AVG(oi.rate),0)::numeric(14,2)'
      WHEN 'orders' THEN 'COUNT(DISTINCT o.id)'
      WHEN 'new_retailers' THEN 'COUNT(DISTINCT o.retailer_id)'
      ELSE 'COALESCE(SUM(oi.quantity),0)::numeric' END;

    v_sql := format($SQL$
      SELECT to_jsonb(t) FROM (
        SELECT %s AS %I, %s AS %I, %s AS %I
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1, 2 ORDER BY 1, 2 LIMIT 5000
      ) t
    $SQL$, v_row_sql, v_row_key, v_col_sql, v_col_key, v_val_sql, v_val_key);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_row_keys IS NULL OR COALESCE(array_length(p_row_keys, 1), 0) = 0 THEN
    v_dims := ARRAY[v_row_key]; v_aliases := ARRAY['grp'];
  ELSE
    v_dims := p_row_keys; v_aliases := p_row_keys;
  END IF;

  v_by_day   := ('order_date' = ANY(v_dims)) OR ('date' = ANY(v_dims));
  v_universe := ('team_member' = ANY(v_dims))
                AND (v_dims <@ ARRAY['team_member','order_date','date']::text[]);

  IF v_universe THEN
    FOR v_i IN 1..array_length(v_dims, 1) LOOP
      v_dim_sql := v_dim_sql || format('%s AS %I, ',
        CASE WHEN v_dims[v_i] IN ('order_date','date') THEN 'base.day::text'
             ELSE 'COALESCE(pr.full_name, pr.username, ''Unknown'')' END,
        v_aliases[v_i]);
      v_group_sql := v_group_sql || v_i::text || ',';
    END LOOP;
    v_group_sql := rtrim(v_group_sql, ',');

    v_sql := format($SQL$
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt
        FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
        GROUP BY retailer_id
      ),
      base AS (
        SELECT user_id, %1$s AS day FROM public.orders
         WHERE order_date::date BETWEEN $1 AND $2 AND cancelled_at IS NULL AND status <> 'cancelled'
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
           AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
        UNION
        SELECT user_id, %2$s FROM public.visits
         WHERE planned_date BETWEEN $1 AND $2
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        UNION
        SELECT user_id, %3$s FROM public.attendance
         WHERE date BETWEEN $1 AND $2
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
      ),
      ord AS (
        SELECT o.user_id, %1$s AS day,
               COUNT(DISTINCT o.id)                                  AS orders,
               COALESCE(SUM(oi.quantity),0)::numeric                 AS quantity,
               COALESCE(AVG(oi.rate),0)::numeric(14,2)               AS rate,
               COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2) AS revenue,
               COUNT(DISTINCT o.retailer_id) FILTER (
                 WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date
               )                                                     AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1, 2
      ),
      vis AS (
        SELECT v.user_id, %2$s AS day,
               COUNT(*) FILTER (WHERE v.status = 'productive')   AS productive,
               COUNT(*) FILTER (WHERE v.status = 'unproductive') AS unproductive,
               COUNT(*) FILTER (WHERE v.status = 'planned')      AS pending
        FROM public.visits v
        WHERE v.planned_date BETWEEN $1 AND $2
          AND ($3::uuid[] IS NULL OR v.user_id = ANY($3::uuid[]))
        GROUP BY 1, 2
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          %4$s
          COALESCE(SUM(ord.quantity),0)::numeric      AS quantity,
          COALESCE(AVG(ord.rate),0)::numeric(14,2)    AS rate,
          COALESCE(SUM(ord.revenue),0)::numeric(14,2) AS revenue,
          COALESCE(SUM(ord.orders),0)                 AS orders,
          COALESCE(SUM(ord.new_retailers),0)          AS new_retailers,
          COALESCE(SUM(vis.productive),0)             AS productive,
          COALESCE(SUM(vis.unproductive),0)           AS unproductive,
          COALESCE(SUM(vis.pending),0)                AS pending
        FROM base
        LEFT JOIN public.profiles pr ON pr.id = base.user_id
        LEFT JOIN ord ON ord.user_id = base.user_id AND ord.day IS NOT DISTINCT FROM base.day
        LEFT JOIN vis ON vis.user_id = base.user_id AND vis.day IS NOT DISTINCT FROM base.day
        GROUP BY %5$s ORDER BY %5$s LIMIT 2000
      ) t
    $SQL$,
      CASE WHEN v_by_day THEN 'order_date::date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'planned_date'     ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'date'             ELSE 'NULL::date' END,
      v_dim_sql, v_group_sql);

    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  FOR v_i IN 1..array_length(v_dims, 1) LOOP
    v_dim_sql := v_dim_sql || format('%s AS %I, ',
      CASE v_dims[v_i]
        WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
        WHEN 'retailer' THEN 'COALESCE(o.retailer_name,''—'')'
        WHEN 'distributor' THEN 'COALESCE(o.distributor_name,''—'')'
        WHEN 'product' THEN 'COALESCE(oi.product_name,''—'')'
        WHEN 'category' THEN 'COALESCE(oi.category,''—'')'
        WHEN 'uom' THEN 'COALESCE(oi.uom_code,''—'')'
        WHEN 'order_date' THEN 'o.order_date::date::text'
        WHEN 'date' THEN 'o.order_date::date::text'
        WHEN 'status' THEN 'COALESCE(o.status,''—'')'
        ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END, v_aliases[v_i]);
    v_group_sql := v_group_sql || v_i::text || ',';
  END LOOP;
  v_group_sql := rtrim(v_group_sql, ',');

  v_sql := format($SQL$
    WITH first_order AS (
      SELECT retailer_id, MIN(order_date::date) AS first_dt
      FROM public.orders
      WHERE cancelled_at IS NULL AND status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
      GROUP BY retailer_id
    )
    SELECT to_jsonb(t) FROM (
      SELECT
        %s
        COALESCE(SUM(oi.quantity),0)::numeric                 AS quantity,
        COALESCE(AVG(oi.rate),0)::numeric(14,2)               AS rate,
        COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2) AS revenue,
        COUNT(DISTINCT o.id)                                  AS orders,
        COUNT(DISTINCT o.retailer_id) FILTER (
          WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date
        )                                                     AS new_retailers
      FROM public.orders o
      JOIN public.order_items oi ON oi.order_id = o.id
      LEFT JOIN public.profiles p ON p.id = o.user_id
      LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
      LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
      WHERE o.order_date::date BETWEEN $1 AND $2
        AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
        AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
      GROUP BY %s ORDER BY %s LIMIT 2000
    ) t
  $SQL$, v_dim_sql, v_group_sql, v_group_sql);

  FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
  LOOP RETURN NEXT v_rec; END LOOP;
END;
$function$$Q1733$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260805102111_fix_sales_report_universe_aggregation.sql', left($Q1733$-- Fix: the universe branch selected pre-aggregated CTE columns alongside a
-- GROUP BY, which Postgres rejects. Wrap them in aggregates so the outer query
-- collapses correctly when several base rows share a dimension value.
CREATE OR REPLACE FUNCTION public.get_sales_report(
  p_layout   text,
  p_rows     text,
  p_columns  text,
  p_values   text[],
  p_filters  jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from     DATE  := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to       DATE  := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user    UUID  := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_distributor   UUID  := NULLIF(p_filters->>'distributor_id','')::UUID;
  v_user_ids      UUID[];
  v_row_key       text  := COALESCE(NULLIF(p_rows,''), 'team_member');
  v_col_key       text  := COALESCE(NULLIF(p_columns,''), 'team_member');
  v_val_key       text  := COALESCE(p_values[1], 'quantity');
  v_row_sql       text;
  v_col_sql       text;
  v_val_sql       text;
  v_sql           text;
  v_rec           JSONB;
  v_dims          text[];
  v_aliases       text[];
  v_dim_sql       text := '';
  v_group_sql     text := '';
  v_i             int;
  v_by_day        boolean;
  v_universe      boolean;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt
        FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY retailer_id
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          o.order_date::date                               AS order_date,
          COALESCE(p.full_name, p.username, 'Unknown')     AS team_member,
          COALESCE(o.beat_name_snapshot, b.beat_name)      AS beat,
          o.retailer_name                                  AS retailer,
          o.distributor_name                               AS distributor,
          oi.product_name                                  AS product,
          oi.category                                      AS category,
          oi.uom_code                                      AS uom,
          o.status                                         AS status,
          COALESCE(oi.quantity,0)::numeric                 AS quantity,
          COALESCE(oi.rate,0)::numeric(14,2)               AS rate,
          COALESCE(oi.quantity * oi.rate,0)::numeric(14,2) AS revenue,
          CASE WHEN fo.first_dt = o.order_date::date
                AND fo.first_dt BETWEEN v_date_from AND v_date_to
               THEN 1 ELSE 0 END                           AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR o.distributor_id = v_distributor)
        ORDER BY o.order_date DESC, o.created_at DESC
        LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_layout = 'matrix' THEN
    v_row_sql := CASE v_row_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_col_sql := CASE v_col_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_val_sql := CASE v_val_key
      WHEN 'revenue' THEN 'COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2)'
      WHEN 'rate' THEN 'COALESCE(AVG(oi.rate),0)::numeric(14,2)'
      WHEN 'orders' THEN 'COUNT(DISTINCT o.id)'
      WHEN 'new_retailers' THEN 'COUNT(DISTINCT o.retailer_id)'
      ELSE 'COALESCE(SUM(oi.quantity),0)::numeric' END;

    v_sql := format($SQL$
      SELECT to_jsonb(t) FROM (
        SELECT %s AS %I, %s AS %I, %s AS %I
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1, 2 ORDER BY 1, 2 LIMIT 5000
      ) t
    $SQL$, v_row_sql, v_row_key, v_col_sql, v_col_key, v_val_sql, v_val_key);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_row_keys IS NULL OR COALESCE(array_length(p_row_keys, 1), 0) = 0 THEN
    v_dims := ARRAY[v_row_key]; v_aliases := ARRAY['grp'];
  ELSE
    v_dims := p_row_keys; v_aliases := p_row_keys;
  END IF;

  v_by_day   := ('order_date' = ANY(v_dims)) OR ('date' = ANY(v_dims));
  v_universe := ('team_member' = ANY(v_dims))
                AND (v_dims <@ ARRAY['team_member','order_date','date']::text[]);

  IF v_universe THEN
    FOR v_i IN 1..array_length(v_dims, 1) LOOP
      v_dim_sql := v_dim_sql || format('%s AS %I, ',
        CASE WHEN v_dims[v_i] IN ('order_date','date') THEN 'base.day::text'
             ELSE 'COALESCE(pr.full_name, pr.username, ''Unknown'')' END,
        v_aliases[v_i]);
      v_group_sql := v_group_sql || v_i::text || ',';
    END LOOP;
    v_group_sql := rtrim(v_group_sql, ',');

    v_sql := format($SQL$
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt
        FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
        GROUP BY retailer_id
      ),
      base AS (
        SELECT user_id, %1$s AS day FROM public.orders
         WHERE order_date::date BETWEEN $1 AND $2 AND cancelled_at IS NULL AND status <> 'cancelled'
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
           AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
        UNION
        SELECT user_id, %2$s FROM public.visits
         WHERE planned_date BETWEEN $1 AND $2
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        UNION
        SELECT user_id, %3$s FROM public.attendance
         WHERE date BETWEEN $1 AND $2
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
      ),
      ord AS (
        SELECT o.user_id, %1$s AS day,
               COUNT(DISTINCT o.id)                                  AS orders,
               COALESCE(SUM(oi.quantity),0)::numeric                 AS quantity,
               COALESCE(AVG(oi.rate),0)::numeric(14,2)               AS rate,
               COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2) AS revenue,
               COUNT(DISTINCT o.retailer_id) FILTER (
                 WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date
               )                                                     AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1, 2
      ),
      vis AS (
        SELECT v.user_id, %2$s AS day,
               COUNT(*) FILTER (WHERE v.status = 'productive')   AS productive,
               COUNT(*) FILTER (WHERE v.status = 'unproductive') AS unproductive,
               COUNT(*) FILTER (WHERE v.status = 'planned')      AS pending
        FROM public.visits v
        WHERE v.planned_date BETWEEN $1 AND $2
          AND ($3::uuid[] IS NULL OR v.user_id = ANY($3::uuid[]))
        GROUP BY 1, 2
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          %4$s
          COALESCE(SUM(ord.quantity),0)::numeric      AS quantity,
          COALESCE(AVG(ord.rate),0)::numeric(14,2)    AS rate,
          COALESCE(SUM(ord.revenue),0)::numeric(14,2) AS revenue,
          COALESCE(SUM(ord.orders),0)                 AS orders,
          COALESCE(SUM(ord.new_retailers),0)          AS new_retailers,
          COALESCE(SUM(vis.productive),0)             AS productive,
          COALESCE(SUM(vis.unproductive),0)           AS unproductive,
          COALESCE(SUM(vis.pending),0)                AS pending
        FROM base
        LEFT JOIN public.profiles pr ON pr.id = base.user_id
        LEFT JOIN ord ON ord.user_id = base.user_id AND ord.day IS NOT DISTINCT FROM base.day
        LEFT JOIN vis ON vis.user_id = base.user_id AND vis.day IS NOT DISTINCT FROM base.day
        GROUP BY %5$s ORDER BY %5$s LIMIT 2000
      ) t
    $SQL$,
      CASE WHEN v_by_day THEN 'order_date::date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'planned_date'     ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'date'             ELSE 'NULL::date' END,
      v_dim_sql, v_group_sql);

    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  FOR v_i IN 1..array_length(v_dims, 1) LOOP
    v_dim_sql := v_dim_sql || format('%s AS %I, ',
      CASE v_dims[v_i]
        WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
        WHEN 'retailer' THEN 'COALESCE(o.retailer_name,''—'')'
        WHEN 'distributor' THEN 'COALESCE(o.distributor_name,''—'')'
        WHEN 'product' THEN 'COALESCE(oi.product_name,''—'')'
        WHEN 'category' THEN 'COALESCE(oi.category,''—'')'
        WHEN 'uom' THEN 'COALESCE(oi.uom_code,''—'')'
        WHEN 'order_date' THEN 'o.order_date::date::text'
        WHEN 'date' THEN 'o.order_date::date::text'
        WHEN 'status' THEN 'COALESCE(o.status,''—'')'
        ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END, v_aliases[v_i]);
    v_group_sql := v_group_sql || v_i::text || ',';
  END LOOP;
  v_group_sql := rtrim(v_group_sql, ',');

  v_sql := format($SQL$
    WITH first_order AS (
      SELECT retailer_id, MIN(order_date::date) AS first_dt
      FROM public.orders
      WHERE cancelled_at IS NULL AND status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        AND ($4::uuid   IS NULL OR distributor_id = $4::uuid)
      GROUP BY retailer_id
    )
    SELECT to_jsonb(t) FROM (
      SELECT
        %s
        COALESCE(SUM(oi.quantity),0)::numeric                 AS quantity,
        COALESCE(AVG(oi.rate),0)::numeric(14,2)               AS rate,
        COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2) AS revenue,
        COUNT(DISTINCT o.id)                                  AS orders,
        COUNT(DISTINCT o.retailer_id) FILTER (
          WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date
        )                                                     AS new_retailers
      FROM public.orders o
      JOIN public.order_items oi ON oi.order_id = o.id
      LEFT JOIN public.profiles p ON p.id = o.user_id
      LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
      LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
      WHERE o.order_date::date BETWEEN $1 AND $2
        AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
        AND ($4::uuid   IS NULL OR o.distributor_id = $4::uuid)
      GROUP BY %s ORDER BY %s LIMIT 2000
    ) t
  $SQL$, v_dim_sql, v_group_sql, v_group_sql);

  FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
  LOOP RETURN NEXT v_rec; END LOOP;
END;
$function$$Q1733$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1734$-- Postgres does not support COUNT(DISTINCT ...) as a window function
-- ("DISTINCT is not implemented for window functions"), which broke the whole
-- TABULAR branch. Precompute per-user order counts in a CTE and join instead.
CREATE OR REPLACE FUNCTION public.get_sales_report(
  p_layout   text, p_rows text, p_columns text, p_values text[], p_filters jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_distributor UUID := NULLIF(p_filters->>'distributor_id','')::UUID;
  v_user_ids UUID[];
  v_row_key text := COALESCE(NULLIF(p_rows,''), 'team_member');
  v_col_key text := COALESCE(NULLIF(p_columns,''), 'team_member');
  v_val_key text := COALESCE(p_values[1], 'quantity');
  v_row_sql text; v_col_sql text; v_val_sql text; v_sql text; v_rec JSONB;
  v_dims text[]; v_aliases text[]; v_dim_sql text := ''; v_group_sql text := '';
  v_i int; v_by_day boolean; v_universe boolean;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN v_user_ids := ARRAY[v_scope_user]; END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY retailer_id
      ),
      user_orders AS (
        SELECT user_id, COUNT(DISTINCT id) AS orders FROM public.orders
        WHERE order_date::date BETWEEN v_date_from AND v_date_to
          AND cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY user_id
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          o.order_date::date                               AS order_date,
          COALESCE(p.full_name, p.username, 'Unknown')     AS team_member,
          COALESCE(o.beat_name_snapshot, b.beat_name)      AS beat,
          o.retailer_name                                  AS retailer,
          o.distributor_name                               AS distributor,
          oi.product_name                                  AS product,
          oi.category                                      AS category,
          oi.uom_code                                      AS uom,
          o.status                                         AS status,
          COALESCE(oi.quantity,0)::numeric                 AS quantity,
          COALESCE(oi.rate,0)::numeric(14,2)               AS rate,
          COALESCE(oi.quantity * oi.rate,0)::numeric(14,2) AS revenue,
          COALESCE(uo.orders,0)                            AS orders,
          CASE WHEN fo.first_dt = o.order_date::date
                AND fo.first_dt BETWEEN v_date_from AND v_date_to
               THEN 1 ELSE 0 END                           AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        LEFT JOIN user_orders uo   ON uo.user_id = o.user_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR o.distributor_id = v_distributor)
        ORDER BY o.order_date DESC, o.created_at DESC LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_layout = 'matrix' THEN
    v_row_sql := CASE v_row_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_col_sql := CASE v_col_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_val_sql := CASE v_val_key
      WHEN 'revenue' THEN 'COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2)'
      WHEN 'rate' THEN 'COALESCE(AVG(oi.rate),0)::numeric(14,2)'
      WHEN 'orders' THEN 'COUNT(DISTINCT o.id)'
      WHEN 'new_retailers' THEN 'COUNT(DISTINCT o.retailer_id)'
      ELSE 'COALESCE(SUM(oi.quantity),0)::numeric' END;
    v_sql := format($SQL$
      SELECT to_jsonb(t) FROM (
        SELECT %s AS %I, %s AS %I, %s AS %I
        FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1,2 ORDER BY 1,2 LIMIT 5000 ) t
    $SQL$, v_row_sql, v_row_key, v_col_sql, v_col_key, v_val_sql, v_val_key);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_row_keys IS NULL OR COALESCE(array_length(p_row_keys,1),0) = 0 THEN
    v_dims := ARRAY[v_row_key]; v_aliases := ARRAY['grp'];
  ELSE v_dims := p_row_keys; v_aliases := p_row_keys; END IF;

  v_by_day := ('order_date' = ANY(v_dims)) OR ('date' = ANY(v_dims));
  v_universe := ('team_member' = ANY(v_dims))
                AND (v_dims <@ ARRAY['team_member','order_date','date']::text[]);

  IF v_universe THEN
    FOR v_i IN 1..array_length(v_dims,1) LOOP
      v_dim_sql := v_dim_sql || format('%s AS %I, ',
        CASE WHEN v_dims[v_i] IN ('order_date','date') THEN 'base.day::text'
             ELSE 'COALESCE(pr.full_name, pr.username, ''Unknown'')' END, v_aliases[v_i]);
      v_group_sql := v_group_sql || v_i::text || ',';
    END LOOP;
    v_group_sql := rtrim(v_group_sql, ',');
    v_sql := format($SQL$
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR distributor_id = $4::uuid) GROUP BY retailer_id ),
      base AS (
        SELECT user_id, %1$s AS day FROM public.orders
         WHERE order_date::date BETWEEN $1 AND $2 AND cancelled_at IS NULL AND status <> 'cancelled'
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
           AND ($4::uuid IS NULL OR distributor_id = $4::uuid)
        UNION SELECT user_id, %2$s FROM public.visits
         WHERE planned_date BETWEEN $1 AND $2 AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        UNION SELECT user_id, %3$s FROM public.attendance
         WHERE date BETWEEN $1 AND $2 AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[])) ),
      ord AS (
        SELECT o.user_id, %1$s AS day, COUNT(DISTINCT o.id) AS orders,
               COALESCE(SUM(oi.quantity),0)::numeric AS quantity,
               COALESCE(AVG(oi.rate),0)::numeric(14,2) AS rate,
               COALESCE(SUM(oi.quantity*oi.rate),0)::numeric(14,2) AS revenue,
               COUNT(DISTINCT o.retailer_id) FILTER (
                 WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date) AS new_retailers
        FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN first_order fo ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN $1 AND $2 AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid) GROUP BY 1,2 ),
      vis AS (
        SELECT v.user_id, %2$s AS day,
               COUNT(*) FILTER (WHERE v.status='productive') AS productive,
               COUNT(*) FILTER (WHERE v.status='unproductive') AS unproductive,
               COUNT(*) FILTER (WHERE v.status='planned') AS pending
        FROM public.visits v WHERE v.planned_date BETWEEN $1 AND $2
          AND ($3::uuid[] IS NULL OR v.user_id = ANY($3::uuid[])) GROUP BY 1,2 )
      SELECT to_jsonb(t) FROM (
        SELECT %4$s
          COALESCE(SUM(ord.quantity),0)::numeric AS quantity,
          COALESCE(AVG(ord.rate),0)::numeric(14,2) AS rate,
          COALESCE(SUM(ord.revenue),0)::numeric(14,2) AS revenue,
          COALESCE(SUM(ord.orders),0) AS orders,
          COALESCE(SUM(ord.new_retailers),0) AS new_retailers,
          COALESCE(SUM(vis.productive),0) AS productive,
          COALESCE(SUM(vis.unproductive),0) AS unproductive,
          COALESCE(SUM(vis.pending),0) AS pending
        FROM base LEFT JOIN public.profiles pr ON pr.id = base.user_id
        LEFT JOIN ord ON ord.user_id = base.user_id AND ord.day IS NOT DISTINCT FROM base.day
        LEFT JOIN vis ON vis.user_id = base.user_id AND vis.day IS NOT DISTINCT FROM base.day
        GROUP BY %5$s ORDER BY %5$s LIMIT 2000 ) t
    $SQL$,
      CASE WHEN v_by_day THEN 'order_date::date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'planned_date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'date' ELSE 'NULL::date' END,
      v_dim_sql, v_group_sql);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  FOR v_i IN 1..array_length(v_dims,1) LOOP
    v_dim_sql := v_dim_sql || format('%s AS %I, ',
      CASE v_dims[v_i]
        WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
        WHEN 'retailer' THEN 'COALESCE(o.retailer_name,''—'')'
        WHEN 'distributor' THEN 'COALESCE(o.distributor_name,''—'')'
        WHEN 'product' THEN 'COALESCE(oi.product_name,''—'')'
        WHEN 'category' THEN 'COALESCE(oi.category,''—'')'
        WHEN 'uom' THEN 'COALESCE(oi.uom_code,''—'')'
        WHEN 'order_date' THEN 'o.order_date::date::text'
        WHEN 'date' THEN 'o.order_date::date::text'
        WHEN 'status' THEN 'COALESCE(o.status,''—'')'
        ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END, v_aliases[v_i]);
    v_group_sql := v_group_sql || v_i::text || ',';
  END LOOP;
  v_group_sql := rtrim(v_group_sql, ',');
  v_sql := format($SQL$
    WITH first_order AS (
      SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
      WHERE cancelled_at IS NULL AND status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        AND ($4::uuid IS NULL OR distributor_id = $4::uuid) GROUP BY retailer_id )
    SELECT to_jsonb(t) FROM (
      SELECT %s
        COALESCE(SUM(oi.quantity),0)::numeric AS quantity,
        COALESCE(AVG(oi.rate),0)::numeric(14,2) AS rate,
        COALESCE(SUM(oi.quantity*oi.rate),0)::numeric(14,2) AS revenue,
        COUNT(DISTINCT o.id) AS orders,
        COUNT(DISTINCT o.retailer_id) FILTER (
          WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date) AS new_retailers
      FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
      LEFT JOIN public.profiles p ON p.id = o.user_id
      LEFT JOIN public.beats b ON b.beat_id = o.beat_id
      LEFT JOIN first_order fo ON fo.retailer_id = o.retailer_id
      WHERE o.order_date::date BETWEEN $1 AND $2
        AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
        AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid)
      GROUP BY %s ORDER BY %s LIMIT 2000 ) t
  $SQL$, v_dim_sql, v_group_sql, v_group_sql);
  FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
  LOOP RETURN NEXT v_rec; END LOOP;
END;
$function$$Q1734$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260805103307_fix_tabular_orders_use_cte_not_window.sql', left($Q1734$-- Postgres does not support COUNT(DISTINCT ...) as a window function
-- ("DISTINCT is not implemented for window functions"), which broke the whole
-- TABULAR branch. Precompute per-user order counts in a CTE and join instead.
CREATE OR REPLACE FUNCTION public.get_sales_report(
  p_layout   text, p_rows text, p_columns text, p_values text[], p_filters jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to   DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_distributor UUID := NULLIF(p_filters->>'distributor_id','')::UUID;
  v_user_ids UUID[];
  v_row_key text := COALESCE(NULLIF(p_rows,''), 'team_member');
  v_col_key text := COALESCE(NULLIF(p_columns,''), 'team_member');
  v_val_key text := COALESCE(p_values[1], 'quantity');
  v_row_sql text; v_col_sql text; v_val_sql text; v_sql text; v_rec JSONB;
  v_dims text[]; v_aliases text[]; v_dim_sql text := ''; v_group_sql text := '';
  v_i int; v_by_day boolean; v_universe boolean;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN v_user_ids := ARRAY[v_scope_user]; END;
  END IF;

  IF p_layout = 'tabular' THEN
    FOR v_rec IN
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY retailer_id
      ),
      user_orders AS (
        SELECT user_id, COUNT(DISTINCT id) AS orders FROM public.orders
        WHERE order_date::date BETWEEN v_date_from AND v_date_to
          AND cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR distributor_id = v_distributor)
        GROUP BY user_id
      )
      SELECT to_jsonb(t) FROM (
        SELECT
          o.order_date::date                               AS order_date,
          COALESCE(p.full_name, p.username, 'Unknown')     AS team_member,
          COALESCE(o.beat_name_snapshot, b.beat_name)      AS beat,
          o.retailer_name                                  AS retailer,
          o.distributor_name                               AS distributor,
          oi.product_name                                  AS product,
          oi.category                                      AS category,
          oi.uom_code                                      AS uom,
          o.status                                         AS status,
          COALESCE(oi.quantity,0)::numeric                 AS quantity,
          COALESCE(oi.rate,0)::numeric(14,2)               AS rate,
          COALESCE(oi.quantity * oi.rate,0)::numeric(14,2) AS revenue,
          COALESCE(uo.orders,0)                            AS orders,
          CASE WHEN fo.first_dt = o.order_date::date
                AND fo.first_dt BETWEEN v_date_from AND v_date_to
               THEN 1 ELSE 0 END                           AS new_retailers
        FROM public.orders o
        JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b   ON b.beat_id = o.beat_id
        LEFT JOIN first_order fo   ON fo.retailer_id = o.retailer_id
        LEFT JOIN user_orders uo   ON uo.user_id = o.user_id
        WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND (v_user_ids IS NULL OR o.user_id = ANY(v_user_ids))
          AND (v_distributor IS NULL OR o.distributor_id = v_distributor)
        ORDER BY o.order_date DESC, o.created_at DESC LIMIT 5000
      ) t
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_layout = 'matrix' THEN
    v_row_sql := CASE v_row_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_col_sql := CASE v_col_key
      WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
      WHEN 'retailer' THEN 'COALESCE(o.retailer_name, ''—'')'
      WHEN 'distributor' THEN 'COALESCE(o.distributor_name, ''—'')'
      WHEN 'order_date' THEN 'o.order_date::date::text'
      WHEN 'date' THEN 'o.order_date::date::text'
      WHEN 'status' THEN 'COALESCE(o.status, ''—'')'
      WHEN 'product' THEN 'COALESCE(oi.product_name, ''—'')'
      WHEN 'category' THEN 'COALESCE(oi.category, ''—'')'
      WHEN 'uom' THEN 'COALESCE(oi.uom_code, ''—'')'
      ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END;
    v_val_sql := CASE v_val_key
      WHEN 'revenue' THEN 'COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2)'
      WHEN 'rate' THEN 'COALESCE(AVG(oi.rate),0)::numeric(14,2)'
      WHEN 'orders' THEN 'COUNT(DISTINCT o.id)'
      WHEN 'new_retailers' THEN 'COUNT(DISTINCT o.retailer_id)'
      ELSE 'COALESCE(SUM(oi.quantity),0)::numeric' END;
    v_sql := format($SQL$
      SELECT to_jsonb(t) FROM (
        SELECT %s AS %I, %s AS %I, %s AS %I
        FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN public.profiles p ON p.id = o.user_id
        LEFT JOIN public.beats b ON b.beat_id = o.beat_id
        WHERE o.order_date::date BETWEEN $1 AND $2
          AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid)
        GROUP BY 1,2 ORDER BY 1,2 LIMIT 5000 ) t
    $SQL$, v_row_sql, v_row_key, v_col_sql, v_col_key, v_val_sql, v_val_key);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  IF p_row_keys IS NULL OR COALESCE(array_length(p_row_keys,1),0) = 0 THEN
    v_dims := ARRAY[v_row_key]; v_aliases := ARRAY['grp'];
  ELSE v_dims := p_row_keys; v_aliases := p_row_keys; END IF;

  v_by_day := ('order_date' = ANY(v_dims)) OR ('date' = ANY(v_dims));
  v_universe := ('team_member' = ANY(v_dims))
                AND (v_dims <@ ARRAY['team_member','order_date','date']::text[]);

  IF v_universe THEN
    FOR v_i IN 1..array_length(v_dims,1) LOOP
      v_dim_sql := v_dim_sql || format('%s AS %I, ',
        CASE WHEN v_dims[v_i] IN ('order_date','date') THEN 'base.day::text'
             ELSE 'COALESCE(pr.full_name, pr.username, ''Unknown'')' END, v_aliases[v_i]);
      v_group_sql := v_group_sql || v_i::text || ',';
    END LOOP;
    v_group_sql := rtrim(v_group_sql, ',');
    v_sql := format($SQL$
      WITH first_order AS (
        SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
        WHERE cancelled_at IS NULL AND status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR distributor_id = $4::uuid) GROUP BY retailer_id ),
      base AS (
        SELECT user_id, %1$s AS day FROM public.orders
         WHERE order_date::date BETWEEN $1 AND $2 AND cancelled_at IS NULL AND status <> 'cancelled'
           AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
           AND ($4::uuid IS NULL OR distributor_id = $4::uuid)
        UNION SELECT user_id, %2$s FROM public.visits
         WHERE planned_date BETWEEN $1 AND $2 AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        UNION SELECT user_id, %3$s FROM public.attendance
         WHERE date BETWEEN $1 AND $2 AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[])) ),
      ord AS (
        SELECT o.user_id, %1$s AS day, COUNT(DISTINCT o.id) AS orders,
               COALESCE(SUM(oi.quantity),0)::numeric AS quantity,
               COALESCE(AVG(oi.rate),0)::numeric(14,2) AS rate,
               COALESCE(SUM(oi.quantity*oi.rate),0)::numeric(14,2) AS revenue,
               COUNT(DISTINCT o.retailer_id) FILTER (
                 WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date) AS new_retailers
        FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
        LEFT JOIN first_order fo ON fo.retailer_id = o.retailer_id
        WHERE o.order_date::date BETWEEN $1 AND $2 AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
          AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
          AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid) GROUP BY 1,2 ),
      vis AS (
        SELECT v.user_id, %2$s AS day,
               COUNT(*) FILTER (WHERE v.status='productive') AS productive,
               COUNT(*) FILTER (WHERE v.status='unproductive') AS unproductive,
               COUNT(*) FILTER (WHERE v.status='planned') AS pending
        FROM public.visits v WHERE v.planned_date BETWEEN $1 AND $2
          AND ($3::uuid[] IS NULL OR v.user_id = ANY($3::uuid[])) GROUP BY 1,2 )
      SELECT to_jsonb(t) FROM (
        SELECT %4$s
          COALESCE(SUM(ord.quantity),0)::numeric AS quantity,
          COALESCE(AVG(ord.rate),0)::numeric(14,2) AS rate,
          COALESCE(SUM(ord.revenue),0)::numeric(14,2) AS revenue,
          COALESCE(SUM(ord.orders),0) AS orders,
          COALESCE(SUM(ord.new_retailers),0) AS new_retailers,
          COALESCE(SUM(vis.productive),0) AS productive,
          COALESCE(SUM(vis.unproductive),0) AS unproductive,
          COALESCE(SUM(vis.pending),0) AS pending
        FROM base LEFT JOIN public.profiles pr ON pr.id = base.user_id
        LEFT JOIN ord ON ord.user_id = base.user_id AND ord.day IS NOT DISTINCT FROM base.day
        LEFT JOIN vis ON vis.user_id = base.user_id AND vis.day IS NOT DISTINCT FROM base.day
        GROUP BY %5$s ORDER BY %5$s LIMIT 2000 ) t
    $SQL$,
      CASE WHEN v_by_day THEN 'order_date::date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'planned_date' ELSE 'NULL::date' END,
      CASE WHEN v_by_day THEN 'date' ELSE 'NULL::date' END,
      v_dim_sql, v_group_sql);
    FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
    LOOP RETURN NEXT v_rec; END LOOP;
    RETURN;
  END IF;

  FOR v_i IN 1..array_length(v_dims,1) LOOP
    v_dim_sql := v_dim_sql || format('%s AS %I, ',
      CASE v_dims[v_i]
        WHEN 'beat' THEN 'COALESCE(o.beat_name_snapshot, b.beat_name, ''—'')'
        WHEN 'retailer' THEN 'COALESCE(o.retailer_name,''—'')'
        WHEN 'distributor' THEN 'COALESCE(o.distributor_name,''—'')'
        WHEN 'product' THEN 'COALESCE(oi.product_name,''—'')'
        WHEN 'category' THEN 'COALESCE(oi.category,''—'')'
        WHEN 'uom' THEN 'COALESCE(oi.uom_code,''—'')'
        WHEN 'order_date' THEN 'o.order_date::date::text'
        WHEN 'date' THEN 'o.order_date::date::text'
        WHEN 'status' THEN 'COALESCE(o.status,''—'')'
        ELSE 'COALESCE(p.full_name, p.username, ''Unknown'')' END, v_aliases[v_i]);
    v_group_sql := v_group_sql || v_i::text || ',';
  END LOOP;
  v_group_sql := rtrim(v_group_sql, ',');
  v_sql := format($SQL$
    WITH first_order AS (
      SELECT retailer_id, MIN(order_date::date) AS first_dt FROM public.orders
      WHERE cancelled_at IS NULL AND status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR user_id = ANY($3::uuid[]))
        AND ($4::uuid IS NULL OR distributor_id = $4::uuid) GROUP BY retailer_id )
    SELECT to_jsonb(t) FROM (
      SELECT %s
        COALESCE(SUM(oi.quantity),0)::numeric AS quantity,
        COALESCE(AVG(oi.rate),0)::numeric(14,2) AS rate,
        COALESCE(SUM(oi.quantity*oi.rate),0)::numeric(14,2) AS revenue,
        COUNT(DISTINCT o.id) AS orders,
        COUNT(DISTINCT o.retailer_id) FILTER (
          WHERE fo.first_dt BETWEEN $1 AND $2 AND fo.first_dt = o.order_date::date) AS new_retailers
      FROM public.orders o JOIN public.order_items oi ON oi.order_id = o.id
      LEFT JOIN public.profiles p ON p.id = o.user_id
      LEFT JOIN public.beats b ON b.beat_id = o.beat_id
      LEFT JOIN first_order fo ON fo.retailer_id = o.retailer_id
      WHERE o.order_date::date BETWEEN $1 AND $2
        AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
        AND ($3::uuid[] IS NULL OR o.user_id = ANY($3::uuid[]))
        AND ($4::uuid IS NULL OR o.distributor_id = $4::uuid)
      GROUP BY %s ORDER BY %s LIMIT 2000 ) t
  $SQL$, v_dim_sql, v_group_sql, v_group_sql);
  FOR v_rec IN EXECUTE v_sql USING v_date_from, v_date_to, v_user_ids, v_distributor
  LOOP RETURN NEXT v_rec; END LOOP;
END;
$function$$Q1734$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1735$-- Field activity per person: hours present, visits and their outcomes, beats
-- covered, when they last ordered, and what they billed in the period.
--
-- Exists because get_sales_report starts from orders, so a rep who was present
-- and billed nothing cannot appear in it at all. This one starts from the person.
--
-- p_filters.zero_sales_only = true narrows it to exactly that group — present in
-- the period, zero orders — which is the "Zero sales" section of the report.
--
-- Same argument shape as the other report RPCs so it plugs into the existing
-- dataset machinery with no edge-function or builder changes.
CREATE OR REPLACE FUNCTION public.get_field_activity_report(
  p_layout   text,
  p_rows     text,
  p_columns  text,
  p_values   text[],
  p_filters  jsonb,
  p_row_keys text[] DEFAULT NULL
)
RETURNS SETOF jsonb
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_date_from  DATE := COALESCE((p_filters->>'date_from')::DATE, CURRENT_DATE - 30);
  v_date_to    DATE := COALESCE((p_filters->>'date_to')::DATE,   CURRENT_DATE);
  v_scope_user UUID := NULLIF(p_filters->>'scope_user_id','')::UUID;
  v_zero_only  BOOLEAN := COALESCE((p_filters->>'zero_sales_only')::boolean, false);
  v_user_ids   UUID[];
  v_rec        JSONB;
BEGIN
  IF v_scope_user IS NOT NULL THEN
    BEGIN
      SELECT ARRAY(SELECT user_id FROM public.get_all_subordinates(v_scope_user)) || v_scope_user
        INTO v_user_ids;
    EXCEPTION WHEN OTHERS THEN
      v_user_ids := ARRAY[v_scope_user];
    END;
  END IF;

  FOR v_rec IN
    WITH base AS (
      SELECT user_id FROM public.attendance
        WHERE date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
      UNION
      SELECT user_id FROM public.visits
        WHERE planned_date BETWEEN v_date_from AND v_date_to
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
      UNION
      SELECT user_id FROM public.orders
        WHERE order_date::date BETWEEN v_date_from AND v_date_to
          AND cancelled_at IS NULL AND status <> 'cancelled'
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
    ),
    att AS (
      SELECT user_id, ROUND(SUM(total_hours)::numeric, 2) AS hours
      FROM public.attendance
      WHERE date BETWEEN v_date_from AND v_date_to GROUP BY user_id
    ),
    vis AS (
      SELECT user_id,
             COUNT(*)                                          AS visits,
             COUNT(*) FILTER (WHERE status = 'productive')      AS productive,
             COUNT(*) FILTER (WHERE status = 'unproductive')    AS unproductive,
             COUNT(*) FILTER (WHERE status = 'planned')         AS pending
      FROM public.visits
      WHERE planned_date BETWEEN v_date_from AND v_date_to GROUP BY user_id
    ),
    ord AS (
      SELECT o.user_id,
             COUNT(DISTINCT o.id)                                  AS orders,
             COALESCE(SUM(oi.quantity),0)::numeric                 AS quantity,
             COALESCE(SUM(oi.quantity * oi.rate),0)::numeric(14,2) AS revenue
      FROM public.orders o
      JOIN public.order_items oi ON oi.order_id = o.id
      WHERE o.order_date::date BETWEEN v_date_from AND v_date_to
        AND o.cancelled_at IS NULL AND o.status <> 'cancelled'
      GROUP BY o.user_id
    ),
    bts AS (
      SELECT user_id, COUNT(DISTINCT beat_id) AS active_beats
      FROM public.beat_plans GROUP BY user_id
    ),
    lastord AS (
      SELECT user_id, MAX(order_date)::date AS last_order_date
      FROM public.orders WHERE cancelled_at IS NULL GROUP BY user_id
    )
    SELECT to_jsonb(t) FROM (
      SELECT
        COALESCE(pr.full_name, pr.username, 'Unknown')  AS team_member,
        COALESCE(a.hours, 0)::numeric                   AS hours,
        COALESCE(v.visits, 0)                           AS visits,
        COALESCE(v.productive, 0)                       AS productive,
        COALESCE(v.unproductive, 0)                     AS unproductive,
        COALESCE(v.pending, 0)                          AS pending,
        COALESCE(bt.active_beats, 0)                    AS active_beats,
        COALESCE(lo.last_order_date::text, 'never')     AS last_order,
        COALESCE(o.orders, 0)                           AS orders,
        COALESCE(o.quantity, 0)::numeric                AS quantity,
        COALESCE(o.revenue, 0)::numeric(14,2)           AS revenue
      FROM base b
      LEFT JOIN public.profiles pr ON pr.id = b.user_id
      LEFT JOIN att a     ON a.user_id  = b.user_id
      LEFT JOIN vis v     ON v.user_id  = b.user_id
      LEFT JOIN ord o     ON o.user_id  = b.user_id
      LEFT JOIN bts bt    ON bt.user_id = b.user_id
      LEFT JOIN lastord lo ON lo.user_id = b.user_id
      WHERE (NOT v_zero_only OR COALESCE(o.orders, 0) = 0)
      ORDER BY COALESCE(o.revenue,0) DESC, COALESCE(a.hours,0) DESC
      LIMIT 2000
    ) t
  LOOP RETURN NEXT v_rec; END LOOP;
END;
