  v_user_id := auth.uid();

  SELECT COALESCE(full_name, username, recovery_email, v_user_id::text)
  INTO v_user_name
  FROM public.profiles
  WHERE id = v_user_id;

  v_old_json := to_jsonb(OLD);

  v_record_id := COALESCE(
    (v_old_json->>'id'),
    (v_old_json->>'beat_id'),
    (v_old_json->>'order_id'),
    'unknown'
  );

