SET measures = (
  SELECT jsonb_agg(
           t.m || jsonb_build_object(
             'format',
             CASE WHEN (d.key, t.m->>'key') IN (
               ('sales',          'revenue'),
               ('sales',          'rate'),
               ('orders',         'total_amount'),
               ('orders',         'subtotal'),
               ('orders',         'discount_amount'),
               ('field_activity', 'revenue')
             ) THEN 'currency' ELSE 'number' END)
           ORDER BY t.ord)
  FROM jsonb_array_elements(d.measures) WITH ORDINALITY AS t(m, ord)
)
