  rls_enabled_table_count  integer,
  rls_disabled_table_count integer,
  function_count           integer,
  trigger_count            integer,
  index_count              integer,
  foreign_key_count        integer,
  enum_count               integer,
  sequence_count           integer,
  extension_count          integer,
  cron_job_count           integer,
  cron_job_active_count    integer,
  edge_function_hint       integer,
  total_row_estimate       bigint,
  db_size_bytes            bigint,
  notes                    text
)$Q1789$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260808132646_db_health_module_tables_and_capture.sql', left($Q1789$-- DB Health module: point-in-time schema inventory so a dropped table/column
