DO $R$ BEGIN EXECUTE $Q1804$-- Capture stays SECURITY DEFINER (needs catalogs) but refuses an unprivileged
-- caller. auth.uid() IS NULL means pg_cron/service_role, which is allowed.
CREATE OR REPLACE FUNCTION public.capture_db_health_snapshot(p_source text DEFAULT 'manual')
RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $fn$
DECLARE v_id uuid;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT public.user_has_permission(auth.uid(), 'admin_db_health', 'can_read') THEN
    RAISE EXCEPTION 'Your profile does not have permission to capture a DB health snapshot';
  END IF;
  SELECT public._capture_db_health_snapshot_impl(p_source) INTO v_id;
  RETURN v_id;
END $fn$$Q1804$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260808132742_db_health_module_query_functions.sql', left($Q1804$-- Capture stays SECURITY DEFINER (needs catalogs) but refuses an unprivileged
