DO $R$ BEGIN EXECUTE $Q1809$CREATE OR REPLACE FUNCTION public.prune_db_health_snapshots(p_keep_days integer DEFAULT 120)
RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path TO 'public'
AS $fn$
DECLARE v_deleted integer;
BEGIN
  WITH gone AS (
    DELETE FROM db_health_snapshots
    WHERE captured_at < now() - make_interval(days => GREATEST(p_keep_days,7))
    RETURNING 1)
  SELECT count(*) INTO v_deleted FROM gone;
  RETURN v_deleted;
END $fn$$Q1809$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260808132742_db_health_module_query_functions.sql', left($Q1809$CREATE OR REPLACE FUNCTION public.prune_db_health_snapshots(p_keep_days integer DEFAULT 120)
