DO $R$ BEGIN EXECUTE $Q1824$CREATE OR REPLACE FUNCTION public.get_retailer_payment_ledger(p_retailer_id uuid)
RETURNS TABLE(
  entry_at        timestamptz,
  entry_type      text,
  reference       text,
  detail          text,
  debit           numeric,
  credit          numeric,
  running_balance numeric,
  payment_method  text,
  order_id        uuid,
  collection_id   uuid,
  order_status    text,
  payment_status  text,
  is_credit_order boolean
)
LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path TO 'public'
AS $fn$
BEGIN
  -- RLS on retailers decides this. No row visible => no ledger.
  IF NOT EXISTS (SELECT 1 FROM retailers r WHERE r.id = p_retailer_id) THEN
    RAISE EXCEPTION 'Your profile does not have permission to view this retailer';
  END IF;

  RETURN QUERY
  SELECT l.entry_at, l.entry_type, l.reference, l.detail, l.debit, l.credit,
         SUM(l.debit - l.credit) OVER (ORDER BY l.entry_at, l.entry_type
                                       ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)
           AS running_balance,
         l.payment_method, l.order_id, l.collection_id,
         l.order_status, l.payment_status, l.is_credit_order
  FROM public._retailer_payment_ledger_impl(p_retailer_id) l
  ORDER BY l.entry_at, l.entry_type;
END $fn$$Q1824$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260809071112_retailer_payment_ledger_and_invoices.sql', left($Q1824$CREATE OR REPLACE FUNCTION public.get_retailer_payment_ledger(p_retailer_id uuid)
