  SELECT e_at, e_type, e_ref, e_detail, e_debit, e_credit,
         SUM(e_debit - e_credit) OVER (ORDER BY e_at, e_type
           ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW),
         e_method, e_order, e_coll, e_ostatus, e_pstatus, e_iscredit
