BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'product_schemes_discount_tax_treatment_check'
  ) THEN
    ALTER TABLE public.product_schemes
      ADD CONSTRAINT product_schemes_discount_tax_treatment_check
      CHECK (discount_tax_treatment IN ('inclusive','exclusive'));
  END IF;
END $$$Q1851$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260809074451_scheme_discount_tax_treatment.sql', left($Q1851$DO $$
