          AND cancelled_at IS NULL AND status NOT IN ('cancelled','replaced')
          AND (v_user_ids IS NULL OR user_id = ANY(v_user_ids))
    ),
    att AS (
      SELECT user_id, ROUND(SUM(total_hours)::numeric, 2) AS hours
      FROM public.attendance
