DROP INDEX IF EXISTS public.idx_report_delivery_dedupe$Q1886$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1887$-- Replacement is deliberately NON-unique: it still serves the
-- "latest delivery for this subscription and period" lookup that the history
-- view and the dispatcher's catch-up check perform, without constraining
-- how many times a period may be delivered.
CREATE INDEX IF NOT EXISTS idx_report_delivery_sub_period_created
  ON public.report_delivery_log USING btree (subscription_id, period, created_at DESC)$Q1887$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260811060600_report_promo_07_delivery_log_append_only.sql', left($Q1887$-- Replacement is deliberately NON-unique: it still serves the
-- "latest delivery for this subscription and period" lookup that the history
-- view and the dispatcher's catch-up check perform, without constraining
-- how many times a period may be delivered.
CREATE INDEX IF NOT EXISTS idx_report_delivery_sub_period_created
  ON public.report_delivery_log USING btree (subscription_id, period, created_at DESC)$Q1887$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1888$-- Report promotion 08 — notification read-path indexes.
--
-- Found while sweeping index parity between staging and production rather than
-- patching one gap at a time. It is NOT part of the report work: production's
-- `notifications` table carries no index at all beyond its primary key, while
-- the notification bell and the Notification History page both filter on
-- (user_id, is_read) ordered by created_at. Every unread-count fetch and every
-- history page load is therefore a sequential scan — over 13,103 rows in
-- production at the time of writing, and growing with each delivery.
--
-- Bringing production to parity with staging. Safe and independent of the rest
-- of the promotion: adding an index changes no behaviour, only cost, and each
-- statement is guarded so this replays cleanly where the indexes already exist.

-- The hot path: unread badge and the paginated history list.
CREATE INDEX IF NOT EXISTS idx_notifications_user_read
  ON public.notifications USING btree (user_id, is_read, created_at DESC)$Q1888$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260811060700_report_promo_08_notification_indexes.sql', left($Q1888$-- Report promotion 08 — notification read-path indexes.
--
-- Found while sweeping index parity between staging and production rather than
-- patching one gap at a time. It is NOT part of the report work: production's
-- `notifications` table carries no index at all beyond its primary key, while
-- the notification bell and the Notification History page both filter on
-- (user_id, is_read) ordered by created_at. Every unread-count fetch and every
-- history page load is therefore a sequential scan — over 13,103 rows in
-- production at the time of writing, and growing with each delivery.
--
-- Bringing production to parity with staging. Safe and independent of the rest
-- of the promotion: adding an index changes no behaviour, only cost, and each
-- statement is guarded so this replays cleanly where the indexes already exist.

-- The hot path: unread badge and the paginated history list.
CREATE INDEX IF NOT EXISTS idx_notifications_user_read
  ON public.notifications USING btree (user_id, is_read, created_at DESC)$Q1888$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1889$-- Partial: only a small minority of notifications are retailer-scoped, so the
-- predicate keeps the index small.
