          INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
          VALUES (p_actor_user_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
        WHEN 'manager' THEN
          SELECT manager_id INTO v_receiver_id FROM employees WHERE user_id=p_actor_user_id;
          IF v_receiver_id IS NOT NULL THEN
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
          END IF;
        WHEN 'hierarchy' THEN
          FOR v_receiver_id IN SELECT public.notif_managers_up_chain(p_actor_user_id) LOOP
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
          END LOOP;
        WHEN 'admin' THEN
          FOR v_receiver_id IN SELECT up.user_id FROM user_profiles up JOIN security_profiles sp ON sp.id=up.profile_id WHERE sp.name='System Administrator' LOOP
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
          END LOOP;
        WHEN 'specific_user' THEN
          IF v_rule.receiver_user_id IS NOT NULL THEN
            INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
            VALUES (v_rule.receiver_user_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
          END IF;
        WHEN 'role' THEN
          IF v_rule.receiver_role IS NOT NULL THEN
            FOR v_receiver_id IN SELECT up.user_id FROM user_profiles up JOIN security_profiles sp ON sp.id=up.profile_id WHERE sp.name=v_rule.receiver_role LOOP
              INSERT INTO notifications (user_id,title,message,type,related_table,related_id,metadata)
              VALUES (v_receiver_id, v_title, v_message, v_notif_type, p_source_table, v_record_uuid, v_meta_out);
            END LOOP;
          END IF;
        ELSE NULL;
      END CASE;
    END LOOP;

  EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'emit_notification_event(%,%) suppressed: % [%] — business write preserved',
      p_event_code, p_source_table, SQLERRM, SQLSTATE;
  END;
END $function$$Q1907$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1908$-- Fire-and-forget hand-off to the AI edge function, mirroring dispatch_push_for_notification.
-- Runs AFTER INSERT and uses net.http_post, so nothing here can slow an order/attendance save.
--
-- Applied to staging via MCP on 2026-08-12, recorded as 20260812171340. Idempotent.

CREATE OR REPLACE FUNCTION public.dispatch_ai_summary_for_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_url text;
  v_secret text;
BEGIN
  IF COALESCE(NEW.metadata->>'ai_pending','') <> 'true' THEN
    RETURN NEW;
  END IF;

  SELECT function_url, trigger_secret INTO v_url, v_secret
  FROM public.push_config WHERE id = true LIMIT 1;

  IF v_url IS NULL OR v_secret IS NULL THEN
    RETURN NEW;
  END IF;

  -- Same project, sibling function.
  v_url := regexp_replace(v_url, '/[^/]+$', '/notification-ai-summary');

  INSERT INTO public.notification_ai_log (notification_id, rule_id, status)
  VALUES (NEW.id, NULLIF(NEW.metadata->>'ai_rule_id','')::uuid, 'pending');

  PERFORM net.http_post(
    url := v_url,
    headers := jsonb_build_object('Content-Type','application/json','x-ai-secret', v_secret),
    body := jsonb_build_object('notification_id', NEW.id)
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Never let enrichment break the notification itself.
  RETURN NEW;
END;
