-- wrote are put back.
update public.visits v
   set status = 'planned',
       check_out_time = null,
       updated_at = now()
  from public.activity_events ae
 where ae.visit_id = v.id
   and ae.activity_type = 'Event'
   and v.status = 'productive'
   and v.check_in_time is null
   and coalesce(ae.status, '') <> 'closed'
   and exists (
     select 1 from public.orders o
      where o.visit_id = v.id and o.status = 'confirmed'
   )$Q1946$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1947$-- Event stock auto-sync hardening.
--
-- Submitted event orders update event_stock_items.sold_qty through an
-- AFTER INSERT trigger on order_items (the client-side RPC
-- apply_event_stock_for_order stays as a fallback and skips when the
-- trigger already recorded the order in event_stock_audit). This
-- migration captures that trigger in the repo and fixes two gaps:
--
-- 1. Auto-created stock rows now carry the order line's unit, so the
--    tracker shows which unit the sold quantity is counted in.
-- 2. Order quantities are converted into the stock row's unit via the
--    UOM master before being added (an order for 2 BOX no longer adds
--    "2" to a row tracked in PIECE). Unmapped/legacy units fall back
--    to 1:1.

ALTER TABLE public.event_stock_audit ADD COLUMN IF NOT EXISTS order_item_id uuid$Q1947$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260814120000_event_stock_auto_sold_sync.sql', left($Q1947$-- Event stock auto-sync hardening.
