   SET status = 'planned',
       check_out_time = null,
       updated_at = now()
  FROM public.activity_events ae
 WHERE ae.visit_id = v.id
   AND ae.activity_type = 'Event'
   AND v.status = 'productive'
   AND v.check_in_time IS NULL
   AND COALESCE(ae.status, '') <> 'closed'
   AND EXISTS (
     SELECT 1 FROM public.orders o
      WHERE o.visit_id = v.id AND o.status = 'confirmed'
   )$Q1961$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260814130000_orders_never_complete_event_visits.sql', left($Q1961$-- 3) Repair: put back event visits the unguarded paths already closed.
