DO $R$ BEGIN EXECUTE $Q1992$-- Restore foreign keys to uom_master that were silently skipped when the
-- columns were added via "ADD COLUMN IF NOT EXISTS ... REFERENCES" on
-- databases where the column already existed (the REFERENCES clause of a
-- skipped ADD COLUMN never runs). PostgREST needs these FKs to resolve the
-- customer-portal catalog embeds:
--   products:      uom_master!products_default_sales_uom_id_fkey
--   enabled_units: uom_master!enabled_units_uom_id_fkey
-- Without them the catalog products query fails and the portal shows
-- "No product found." for every retailer.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'products_default_sales_uom_id_fkey'
      AND conrelid = 'public.products'::regclass
  ) THEN
    ALTER TABLE public.products
      ADD CONSTRAINT products_default_sales_uom_id_fkey
      FOREIGN KEY (default_sales_uom_id) REFERENCES public.uom_master(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'enabled_units_uom_id_fkey'
      AND conrelid = 'public.enabled_units'::regclass
  ) THEN
    ALTER TABLE public.enabled_units
      ADD CONSTRAINT enabled_units_uom_id_fkey
      FOREIGN KEY (uom_id) REFERENCES public.uom_master(id);
  END IF;
END $$$Q1992$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260826090000_restore_uom_foreign_keys.sql', left($Q1992$-- Restore foreign keys to uom_master that were silently skipped when the
-- columns were added via "ADD COLUMN IF NOT EXISTS ... REFERENCES" on
-- databases where the column already existed (the REFERENCES clause of a
-- skipped ADD COLUMN never runs). PostgREST needs these FKs to resolve the
-- customer-portal catalog embeds:
--   products:      uom_master!products_default_sales_uom_id_fkey
--   enabled_units: uom_master!enabled_units_uom_id_fkey
-- Without them the catalog products query fails and the portal shows
-- "No product found." for every retailer.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'products_default_sales_uom_id_fkey'
      AND conrelid = 'public.products'::regclass
  ) THEN
    ALTER TABLE public.products
      ADD CONSTRAINT products_default_sales_uom_id_fkey
      FOREIGN KEY (default_sales_uom_id) REFERENCES public.uom_master(id);
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM pg_constraint
    WHERE conname = 'enabled_units_uom_id_fkey'
      AND conrelid = 'public.enabled_units'::regclass
  ) THEN
    ALTER TABLE public.enabled_units
      ADD CONSTRAINT enabled_units_uom_id_fkey
      FOREIGN KEY (uom_id) REFERENCES public.uom_master(id);
  END IF;
END $$$Q1992$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1993$-- Restore the products.unit column, which exists on preprod (text NOT NULL
-- DEFAULT 'piece') and is selected by the customer-portal catalog and prices
-- queries, but had been dropped out-of-band on the staging database. Its
-- absence made every portal products query fail with 400 ("column
-- products.unit does not exist") and the catalog showed "No product found.".
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'unit'
  ) THEN
    ALTER TABLE public.products
      ADD COLUMN unit text NOT NULL DEFAULT 'piece';
  END IF;
END $$$Q1993$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260826100000_restore_products_unit_column.sql', left($Q1993$-- Restore the products.unit column, which exists on preprod (text NOT NULL
-- DEFAULT 'piece') and is selected by the customer-portal catalog and prices
-- queries, but had been dropped out-of-band on the staging database. Its
-- absence made every portal products query fail with 400 ("column
-- products.unit does not exist") and the catalog showed "No product found.".
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public' AND table_name = 'products' AND column_name = 'unit'
  ) THEN
    ALTER TABLE public.products
      ADD COLUMN unit text NOT NULL DEFAULT 'piece';
  END IF;
END $$$Q1993$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q1994$-- Fix the target-tier gamification pipeline (e.g. the "Quantity target" activity).
--
-- Why: gam_evaluate_target_tiers awards points from user_period_targets.achievement_percent,
-- but nothing ever populated that table — the admin FY-plan screens write to
-- user_business_plans / user_business_plan_months instead. On top of that, the KPI actuals
-- machinery (calculate_user_kpi_actual, update_revenue_actual) targets legacy kpi_keys
-- ('revenue_contribution', …) that no longer exist in target_kpi_definitions (current keys:
-- quantity, revenue, visits, retailer_activation), and the tier evaluator ignored
-- gamification_actions.validity_from/validity_to.
--
-- This migration is self-contained per environment: it (re)defines the bridge + actuals
-- functions, wires triggers, reschedules the cron, and runs the backfill sync at the end.
-- Deploying it to another project brings that project's own business-plan targets into
-- user_period_targets automatically.

-- ---------------------------------------------------------------------------
-- 1. Quantity actuals: total ordered quantity for a user in a period.
--    Mirrors calculate_revenue_contribution's status filter; excludes BOGO free
--    lines (rate 0, category 'Free Item') so gifted stock doesn't count as sales.
-- ---------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.calculate_order_quantity(p_user_id uuid, p_start date, p_end date)
RETURNS numeric
LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public
AS $$
  SELECT COALESCE(SUM(oi.quantity), 0)
  FROM public.order_items oi
  JOIN public.orders o ON o.id = oi.order_id
  WHERE o.user_id = p_user_id
    AND o.status IN ('confirmed', 'delivered')
    AND o.order_date BETWEEN p_start AND p_end
    AND NOT (COALESCE(oi.rate, 0) = 0 AND oi.category = 'Free Item');
