DO $R$ BEGIN EXECUTE $Q2052$CREATE OR REPLACE FUNCTION public.get_missed_day_retailers(p_user uuid, p_date date)
RETURNS TABLE(visit_id uuid, retailer_id uuid, retailer_name text, city text, beat_id text, beat_name text)
LANGUAGE plpgsql
STABLE SECURITY DEFINER
SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT (p_user = auth.uid() OR public.is_subordinate_of(auth.uid(), p_user)) THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT v.id, v.retailer_id, r.name, r.city, r.beat_id, r.beat_name
  FROM visits v
  LEFT JOIN retailers r ON r.id = v.retailer_id
  WHERE v.user_id = p_user
    AND v.planned_date = p_date
    AND v.status IN ('planned','cancelled')
  ORDER BY r.name NULLS LAST;
END;
$function$$Q2052$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260909063601_83e141c7-c306-4ab4-952b-d3915427e5f9.sql', left($Q2052$CREATE OR REPLACE FUNCTION public.get_missed_day_retailers(p_user uuid, p_date date)
