DO $R$ BEGIN EXECUTE $Q2053$CREATE OR REPLACE FUNCTION public.reschedule_missed_visits(p_user uuid, p_from_date date, p_visit_ids uuid[], p_to_date date DEFAULT NULL::date)
RETURNS TABLE(moved integer, to_date date)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path TO 'public'
AS $function$
DECLARE
  v_to date;
  v_count integer;
BEGIN
  IF NOT (p_user = auth.uid() OR public.is_subordinate_of(auth.uid(), p_user)) THEN
    RETURN;
  END IF;

  v_to := COALESCE(p_to_date, public.next_free_day(p_user, p_from_date));
  IF v_to IS NULL THEN
    RAISE EXCEPTION 'No free day available this month';
  END IF;

  WITH updated AS (
    UPDATE visits v
    SET planned_date = v_to,
        status = 'planned',
        cancel_source = NULL,
        is_rescheduled = true,
        rescheduled_from_date = p_from_date,
        updated_at = now()
    WHERE v.user_id = p_user
      AND v.planned_date = p_from_date
      AND v.status IN ('planned','cancelled')
      AND v.id = ANY(p_visit_ids)
      AND NOT EXISTS (
        SELECT 1 FROM visits v2
        WHERE v2.user_id = p_user
          AND v2.retailer_id = v.retailer_id
          AND v2.planned_date = v_to
          AND v2.status = 'planned'
      )
    RETURNING 1
  )
  SELECT COUNT(*)::integer INTO v_count FROM updated;

  moved := v_count;
  to_date := v_to;
  RETURN NEXT;
END;
$function$$Q2053$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260909063601_83e141c7-c306-4ab4-952b-d3915427e5f9.sql', left($Q2053$CREATE OR REPLACE FUNCTION public.reschedule_missed_visits(p_user uuid, p_from_date date, p_visit_ids uuid[], p_to_date date DEFAULT NULL::date)
