DO $R$ BEGIN EXECUTE $Q2075$CREATE OR REPLACE FUNCTION public.try_invoice_compression_lock(p_key INTEGER)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = public
AS $$
DECLARE
  v_locked_at TIMESTAMPTZ;
BEGIN
  INSERT INTO public.invoice_compression_lock (key, locked_at)
  VALUES (p_key, NULL)
  ON CONFLICT (key) DO NOTHING;

  SELECT locked_at INTO v_locked_at
  FROM public.invoice_compression_lock
  WHERE key = p_key
  FOR UPDATE;

  IF v_locked_at IS NOT NULL AND v_locked_at > now() - INTERVAL '10 minutes' THEN
    RETURN FALSE;
  END IF;

  UPDATE public.invoice_compression_lock SET locked_at = now() WHERE key = p_key;
  RETURN TRUE;
END;
$$$Q2075$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260910123618_61512c98-0e5f-4f1f-ac16-f1a056e6682d.sql', left($Q2075$CREATE OR REPLACE FUNCTION public.try_invoice_compression_lock(p_key INTEGER)
