    CASE WHEN count(*) FILTER (WHERE is_planned) > 0
      THEN round((count(*) FILTER (WHERE is_productive)::numeric
                  / count(*) FILTER (WHERE is_planned)) * 100, 2)
      ELSE 0 END,
    v_start, v_end
  FROM scored;
END;
