DO $R$ BEGIN EXECUTE $Q2186$-- --------------------------------------------- P7: settle on engine outcome

create or replace function public.tg_gam_redemption_approval_complete()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
BEGIN
  IF NEW.entity_type <> 'gamification_redemption' THEN RETURN NEW; END IF;
  IF NEW.status = OLD.status THEN RETURN NEW; END IF;

  IF NEW.status = 'approved' THEN
    PERFORM gam_settle_redemption(NEW.entity_id, true, NEW.final_approved_by, NULL);
  ELSIF NEW.status = 'rejected' THEN
    PERFORM gam_settle_redemption(NEW.entity_id, false, NEW.final_approved_by,
             (SELECT rejection_reason FROM approval_steps
               WHERE approval_request_id = NEW.id AND status='rejected'
               ORDER BY action_taken_at DESC LIMIT 1));
  END IF;
  RETURN NEW;
END; $function$$Q2186$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260924090000_gam_policy_recovered_from_staging.sql', left($Q2186$-- --------------------------------------------- P7: settle on engine outcome

