  add column if not exists approval_modes text[]$Q2267$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20260924170000_approval_routing_multi_select.sql', left($Q2267$-- Route to SEVERAL kinds of approver at once.
