            jsonb_build_object('modes', v_modes, 'approvers', array_length(v_ids, 1)));
    RETURN v_request_id;
  END IF;

  -- ------------------------------------------------- unchanged: reporting chain
  FOR v_chain IN SELECT manager_id, level FROM get_reporting_chain(p_requester_id) ORDER BY level
