-- base_unit, not conversion_factor. Net weight is read as its own thing.
--
-- Snapshotted rather than joined at read time because a milestone that has
-- already been judged must not silently re-judge itself when somebody edits a
-- product's weight months later. The trigger fills it from the variant first,
-- then the product, so every order-writing path gets it -- cart, van sales,
-- counter sale -- without any of them having to know about it.
alter table public.order_items
  add column if not exists net_weight_g numeric$Q2340$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q2341$comment on column public.order_items.net_weight_g is
  'Net weight in grams of ONE selling unit, snapshotted from the variant or product when the line was written. Line weight = quantity * net_weight_g. Null means the product has no net weight configured, so the line cannot be weighed.'$Q2341$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261009150000_order_items_net_weight_snapshot.sql', left($Q2341$comment on column public.order_items.net_weight_g is
  'Net weight in grams of ONE selling unit, snapshotted from the variant or product when the line was written. Line weight = quantity * net_weight_g. Null means the product has no net weight configured, so the line cannot be weighed.'$Q2341$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q2342$create or replace function public.order_items_capture_net_weight()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $function$
BEGIN
  IF NEW.net_weight_g IS NULL THEN
    SELECT NULLIF(pv.net_weight_g, 0) INTO NEW.net_weight_g
    FROM public.product_variants pv WHERE pv.id = NEW.variant_id;
  END IF;

  IF NEW.net_weight_g IS NULL THEN
    SELECT NULLIF(p.net_weight_g, 0) INTO NEW.net_weight_g
    FROM public.products p WHERE p.id = NEW.product_id;
  END IF;

  RETURN NEW;
END;
