DO $R$ BEGIN EXECUTE $Q2356$revoke all on function public.gam_award_order_milestones(uuid, uuid, uuid, boolean) from public$Q2356$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261009170000_gam_awarder_weight_context.sql', left($Q2356$revoke all on function public.gam_award_order_milestones(uuid, uuid, uuid, boolean) from public$Q2356$,400), SQLERRM, SQLSTATE); END $R$;
