      'is_award_rung', t.order_ordinal = v_ordinal,
      'met', public.gam_milestone_met(gp.retailer_id, t.order_ordinal, t.basis,
                                      t.operator, t.threshold),
      'event_value', CASE WHEN v_full THEN
