  'The warehouse this van loaded from. Settling deducts from this warehouse specifically; when null it falls back to the distributor''s default warehouse.'$Q2391$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261013130000_van_stock_source_warehouse.sql', left($Q2391$comment on column public.van_stock.warehouse_id is
