    -- unit and an inventory unit is how a stock ledger acquires numbers nobody
    -- can explain.
    IF COALESCE(NULLIF(TRIM(LOWER(it.unit)),''), 'x')
       IS DISTINCT FROM COALESCE(NULLIF(TRIM(LOWER(inv.unit)),''), 'x') THEN
