DO $R$ BEGIN EXECUTE $Q2409$-- The roster the overview lists against, so somebody who earned nothing is
-- shown at zero instead of being absent. Same definition of "active" as above,
-- kept in the database so the list and the totals can never disagree.
create or replace function public.gam_active_people()
returns table(id uuid, full_name text)
language sql
stable
security definer
set search_path to 'public'
as $$
  select pr.id,
         coalesce(nullif(btrim(pr.full_name), ''), 'Unnamed')
    from public.profiles pr
    left join public.employees e on e.user_id = pr.id
   where pr.is_active = true
     and (e.date_of_exit is null or e.date_of_exit > now())
   -- a person with more than one employee row must still be one row here
   group by pr.id, pr.full_name
   order by 2;
$$$Q2409$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261014120000_gam_overview_active_roster.sql', left($Q2409$-- The roster the overview lists against, so somebody who earned nothing is
