                  when 'ADJUST_INCREASE' then 'ADJUSTMENT_IN'
                  when 'ADJUST_DECREASE' then 'ADJUSTMENT_OUT'
                  when 'RETURN_IN'       then 'RETURN'
                  when 'RETURN_OUT'      then 'RETURN_TO_COMPANY'
