  and t.running_balance is distinct from r.rb$Q2538$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261022110000_ledger_running_balance_rebuild.sql', left($Q2538$-- Rebuild: replay every stream in seq order.
