DO $R$ BEGIN EXECUTE $Q2570$-- execute_stock_action stamped the literal 'pcs' on every inventory row it
-- created, and on the ledger row when the inventory row was new.
--
-- The comment it carried -- "products.unit was removed from schema" -- is not
-- true: products.unit still exists. It holds the pre-UOM-migration text, which
-- reads 'piece' for 21 active products whose configured base is GRAM. So the
-- function replaced a stale column with a hardcoded guess rather than reading
-- the configured base at all.
--
-- The cost is not cosmetic. dms_settle_van_day refuses a line when
-- normalise_unit(van line) differs from normalise_unit(inventory row), and
-- normalise_unit('pcs') is 'piece'. An opening stock entry on a gram product
-- therefore created a row that van settlement would refuse for ever after.
--
-- The base now comes from product_uom_mapping -- the configured source the
-- inventory screens, order entry and settlement all read -- falling back to
-- products.base_unit, then the legacy products.unit, and only then to 'pcs',
-- so a product with no configuration at all behaves as it did before.
--
-- An existing inventory row still keeps its own unit: COALESCE reaches the
-- resolved base only when the row is being created. Correcting units already
-- written is a separate, reviewed change.

CREATE OR REPLACE FUNCTION public.execute_stock_action(p_distributor_id uuid, p_product_id uuid, p_action text, p_quantity integer, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_batch_no text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date, p_reference_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_supplier_batch_code text DEFAULT NULL::text, p_mfg_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inventory RECORD;
  v_new_available INTEGER;
  v_new_reserved INTEGER;
  v_new_damaged INTEGER;
  v_new_expired INTEGER;
  v_new_quantity INTEGER;
  v_txn_type TEXT;
  v_movement TEXT;
  v_batch_id UUID;
  v_wh_id UUID;
  v_system_batch_code TEXT;
  v_signed_qty INTEGER;
  v_product_name TEXT;
  v_product_unit TEXT;
  v_base_unit TEXT;
BEGIN
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity must be positive');
  END IF;

  v_wh_id := p_warehouse_id;
  IF v_wh_id IS NULL THEN
    SELECT id INTO v_wh_id
    FROM public.warehouses
    WHERE distributor_id = p_distributor_id AND is_default = true
    LIMIT 1;
  END IF;

  IF v_wh_id IS NULL THEN
    INSERT INTO public.warehouses (distributor_id, name, code, is_default)
    VALUES (p_distributor_id, 'Main Warehouse', 'MAIN', true)
    ON CONFLICT (distributor_id, name) DO NOTHING
    RETURNING id INTO v_wh_id;

    IF v_wh_id IS NULL THEN
      SELECT id INTO v_wh_id FROM public.warehouses
      WHERE distributor_id = p_distributor_id AND name = 'Main Warehouse'
      LIMIT 1;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses
    WHERE id = v_wh_id AND distributor_id = p_distributor_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid warehouse for this distributor');
  END IF;

  SELECT * INTO v_inventory
  FROM public.distributor_inventory
  WHERE distributor_id = p_distributor_id
    AND product_id = p_product_id
    AND warehouse_id = v_wh_id
  FOR UPDATE;

  IF NOT FOUND AND p_action NOT IN ('OPENING_STOCK', 'GRN') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Product not found in inventory');
  END IF;

  v_new_quantity := COALESCE(v_inventory.quantity, 0);
  v_new_reserved := COALESCE(v_inventory.reserved_quantity, 0);
  v_new_damaged := COALESCE(v_inventory.damaged_quantity, 0);
  v_new_expired := COALESCE(v_inventory.expired_quantity, 0);

  -- The product's configured base unit, in the order the rest of the system
  -- trusts it: the UOM mapping first, then products.base_unit, then the
  -- legacy text column, and 'pcs' only when a product has no units at all.
  SELECT COALESCE(
           (SELECT u.code
              FROM public.product_uom_mapping m
              JOIN public.uom_master u ON u.id = m.uom_id
             WHERE m.product_id = p.id
               AND m.is_base
               AND COALESCE(m.is_active, true)
             LIMIT 1),
           NULLIF(TRIM(p.base_unit), ''),
           NULLIF(TRIM(p.unit), ''),
           'pcs')
    INTO v_base_unit
  FROM public.products p
  WHERE p.id = p_product_id;

  v_base_unit := COALESCE(v_base_unit, 'pcs');

  -- Resolve product metadata for ledger row (name/unit). An existing row keeps
  -- the unit it already carries; only a new row takes the configured base.
  SELECT COALESCE(v_inventory.product_name, p.name, 'Product'),
         COALESCE(v_inventory.unit, v_base_unit)
    INTO v_product_name, v_product_unit
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_product_name IS NULL THEN
    v_product_name := COALESCE(v_inventory.product_name, 'Product');
    v_product_unit := COALESCE(v_inventory.unit, v_base_unit);
  END IF;

  IF p_action IN ('OPENING_STOCK', 'GRN') THEN
    IF p_batch_no IS NULL OR TRIM(p_batch_no) = '' THEN
      v_system_batch_code := public.generate_system_batch_code(v_wh_id, p_product_id, CURRENT_DATE);
    ELSE
      v_system_batch_code := TRIM(p_batch_no);
    END IF;
  ELSE
    v_system_batch_code := p_batch_no;
  END IF;

  CASE p_action
    WHEN 'OPENING_STOCK' THEN
      IF v_inventory.id IS NULL THEN
        INSERT INTO public.distributor_inventory (
          distributor_id, product_id, product_name, quantity,
          reserved_quantity, damaged_quantity, expired_quantity,
          unit, batch_number, expiry_date, warehouse_id
        )
        SELECT p_distributor_id, p_product_id, COALESCE(p.name, 'Product'), p_quantity,
               0, 0, 0, v_base_unit, v_system_batch_code, p_expiry_date, v_wh_id
        FROM public.products p WHERE p.id = p_product_id;

        IF NOT FOUND THEN
          INSERT INTO public.distributor_inventory (
            distributor_id, product_id, product_name, quantity,
            reserved_quantity, damaged_quantity, expired_quantity,
            unit, warehouse_id
          ) VALUES (
            p_distributor_id, p_product_id, COALESCE(p_notes, 'Product'), p_quantity,
            0, 0, 0, v_base_unit, v_wh_id
          );
        END IF;

        v_new_quantity := p_quantity;
      ELSE
        v_new_quantity := v_new_quantity + p_quantity;
      END IF;

      INSERT INTO public.inventory_batches (
        distributor_id, product_id, batch_no, system_batch_code, supplier_batch_code,
        mfg_date, expiry_date, quantity, available_qty, warehouse_id
      ) VALUES (
        p_distributor_id, p_product_id, v_system_batch_code, v_system_batch_code, p_supplier_batch_code,
        p_mfg_date, p_expiry_date, p_quantity, p_quantity, v_wh_id
      )
      ON CONFLICT (distributor_id, product_id, batch_no, warehouse_id)
      DO UPDATE SET
        available_qty = public.inventory_batches.available_qty + EXCLUDED.available_qty,
        quantity = public.inventory_batches.quantity + EXCLUDED.quantity,
        supplier_batch_code = COALESCE(EXCLUDED.supplier_batch_code, public.inventory_batches.supplier_batch_code),
        mfg_date = COALESCE(EXCLUDED.mfg_date, public.inventory_batches.mfg_date),
        expiry_date = COALESCE(EXCLUDED.expiry_date, public.inventory_batches.expiry_date)
      RETURNING id INTO v_batch_id;

      v_txn_type := 'OPENING_STOCK';
      v_movement := 'NULL -> Available';
      v_signed_qty := p_quantity;

    WHEN 'GRN' THEN
      IF v_inventory.id IS NULL THEN
        INSERT INTO public.distributor_inventory (
          distributor_id, product_id, product_name, quantity,
          reserved_quantity, damaged_quantity, expired_quantity,
          unit, batch_number, expiry_date, warehouse_id
        )
        SELECT p_distributor_id, p_product_id, COALESCE(p.name, 'Product'), p_quantity,
               0, 0, 0, v_base_unit, v_system_batch_code, p_expiry_date, v_wh_id
        FROM public.products p WHERE p.id = p_product_id;

        IF NOT FOUND THEN
          INSERT INTO public.distributor_inventory (
            distributor_id, product_id, product_name, quantity,
            reserved_quantity, damaged_quantity, expired_quantity,
            unit, warehouse_id
          ) VALUES (
            p_distributor_id, p_product_id, COALESCE(p_notes, 'Product'), p_quantity,
            0, 0, 0, v_base_unit, v_wh_id
          );
        END IF;
        v_new_quantity := p_quantity;
      ELSE
        v_new_quantity := v_new_quantity + p_quantity;
      END IF;

      INSERT INTO public.inventory_batches (
        distributor_id, product_id, batch_no, system_batch_code, supplier_batch_code,
        mfg_date, expiry_date, quantity, available_qty, warehouse_id
      ) VALUES (
        p_distributor_id, p_product_id, v_system_batch_code, v_system_batch_code, p_supplier_batch_code,
        p_mfg_date, p_expiry_date, p_quantity, p_quantity, v_wh_id
      )
      ON CONFLICT (distributor_id, product_id, batch_no, warehouse_id)
      DO UPDATE SET
        available_qty = public.inventory_batches.available_qty + EXCLUDED.available_qty,
        quantity = public.inventory_batches.quantity + EXCLUDED.quantity,
        supplier_batch_code = COALESCE(EXCLUDED.supplier_batch_code, public.inventory_batches.supplier_batch_code),
        mfg_date = COALESCE(EXCLUDED.mfg_date, public.inventory_batches.mfg_date),
        expiry_date = COALESCE(EXCLUDED.expiry_date, public.inventory_batches.expiry_date)
      RETURNING id INTO v_batch_id;

      v_txn_type := 'GRN';
      v_movement := 'Inward -> Available';
      v_signed_qty := p_quantity;

    WHEN 'RESERVE' THEN
      IF v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock to reserve');
      END IF;
      v_new_reserved := v_new_reserved + p_quantity;
      v_txn_type := 'RESERVE';
      v_movement := 'Available -> Reserved';
      v_signed_qty := p_quantity;

    WHEN 'RELEASE' THEN
      IF v_new_reserved < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot release more than reserved quantity');
      END IF;
      v_new_reserved := v_new_reserved - p_quantity;
      v_txn_type := 'RELEASE';
      v_movement := 'Reserved -> Available';
      v_signed_qty := p_quantity;

    WHEN 'MARK_DAMAGED' THEN
      v_new_available := v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired;
      IF v_new_available < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock');
      END IF;
      v_new_damaged := v_new_damaged + p_quantity;
      v_txn_type := 'MARK_DAMAGED';
      v_movement := 'Available -> Damaged';
      v_signed_qty := p_quantity;

    WHEN 'MARK_EXPIRED' THEN
      v_new_available := v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired;
      IF v_new_available < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock');
      END IF;
      v_new_expired := v_new_expired + p_quantity;
      v_txn_type := 'MARK_EXPIRED';
      v_movement := 'Available -> Expired';
      v_signed_qty := p_quantity;

    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Unknown action: ' || p_action);
  END CASE;

  IF v_inventory.id IS NOT NULL THEN
    UPDATE public.distributor_inventory
    SET quantity = v_new_quantity,
        reserved_quantity = v_new_reserved,
        damaged_quantity = v_new_damaged,
        expired_quantity = v_new_expired,
        updated_at = now()
    WHERE id = v_inventory.id;
  END IF;

  INSERT INTO public.distributor_inventory_transactions (
    distributor_id, product_id, product_name, transaction_type, balance_qty,
    running_balance, unit, notes, created_by, batch_number,
    reference_type, reference_id, reference_number, warehouse_id, expiry_date
  ) VALUES (
    p_distributor_id, p_product_id, v_product_name, v_txn_type, v_signed_qty,
    v_new_quantity, v_product_unit, p_notes, p_created_by, v_system_batch_code,
    NULL, p_reference_id, p_reference_number, v_wh_id, p_expiry_date
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'quantity', p_quantity,
    'warehouse_id', v_wh_id,
    'system_batch_code', v_system_batch_code,
    'new_total', v_new_quantity,
    'new_available', v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired,
    'new_reserved', v_new_reserved,
    'new_damaged', v_new_damaged,
    'new_expired', v_new_expired
  );
END;
$function$$Q2570$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261028100000_stock_action_writes_configured_base_unit.sql', left($Q2570$-- execute_stock_action stamped the literal 'pcs' on every inventory row it
-- created, and on the ledger row when the inventory row was new.
--
-- The comment it carried -- "products.unit was removed from schema" -- is not
-- true: products.unit still exists. It holds the pre-UOM-migration text, which
-- reads 'piece' for 21 active products whose configured base is GRAM. So the
-- function replaced a stale column with a hardcoded guess rather than reading
-- the configured base at all.
--
-- The cost is not cosmetic. dms_settle_van_day refuses a line when
-- normalise_unit(van line) differs from normalise_unit(inventory row), and
-- normalise_unit('pcs') is 'piece'. An opening stock entry on a gram product
-- therefore created a row that van settlement would refuse for ever after.
--
-- The base now comes from product_uom_mapping -- the configured source the
-- inventory screens, order entry and settlement all read -- falling back to
-- products.base_unit, then the legacy products.unit, and only then to 'pcs',
-- so a product with no configuration at all behaves as it did before.
--
-- An existing inventory row still keeps its own unit: COALESCE reaches the
-- resolved base only when the row is being created. Correcting units already
-- written is a separate, reviewed change.

CREATE OR REPLACE FUNCTION public.execute_stock_action(p_distributor_id uuid, p_product_id uuid, p_action text, p_quantity integer, p_notes text DEFAULT NULL::text, p_created_by uuid DEFAULT NULL::uuid, p_warehouse_id uuid DEFAULT NULL::uuid, p_batch_no text DEFAULT NULL::text, p_expiry_date date DEFAULT NULL::date, p_reference_id uuid DEFAULT NULL::uuid, p_reference_number text DEFAULT NULL::text, p_supplier_batch_code text DEFAULT NULL::text, p_mfg_date date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_inventory RECORD;
  v_new_available INTEGER;
  v_new_reserved INTEGER;
  v_new_damaged INTEGER;
  v_new_expired INTEGER;
  v_new_quantity INTEGER;
  v_txn_type TEXT;
  v_movement TEXT;
  v_batch_id UUID;
  v_wh_id UUID;
  v_system_batch_code TEXT;
  v_signed_qty INTEGER;
  v_product_name TEXT;
  v_product_unit TEXT;
  v_base_unit TEXT;
BEGIN
  IF p_quantity <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Quantity must be positive');
  END IF;

  v_wh_id := p_warehouse_id;
  IF v_wh_id IS NULL THEN
    SELECT id INTO v_wh_id
    FROM public.warehouses
    WHERE distributor_id = p_distributor_id AND is_default = true
    LIMIT 1;
  END IF;

  IF v_wh_id IS NULL THEN
    INSERT INTO public.warehouses (distributor_id, name, code, is_default)
    VALUES (p_distributor_id, 'Main Warehouse', 'MAIN', true)
    ON CONFLICT (distributor_id, name) DO NOTHING
    RETURNING id INTO v_wh_id;

    IF v_wh_id IS NULL THEN
      SELECT id INTO v_wh_id FROM public.warehouses
      WHERE distributor_id = p_distributor_id AND name = 'Main Warehouse'
      LIMIT 1;
    END IF;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.warehouses
    WHERE id = v_wh_id AND distributor_id = p_distributor_id
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid warehouse for this distributor');
  END IF;

  SELECT * INTO v_inventory
  FROM public.distributor_inventory
  WHERE distributor_id = p_distributor_id
    AND product_id = p_product_id
    AND warehouse_id = v_wh_id
  FOR UPDATE;

  IF NOT FOUND AND p_action NOT IN ('OPENING_STOCK', 'GRN') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Product not found in inventory');
  END IF;

  v_new_quantity := COALESCE(v_inventory.quantity, 0);
  v_new_reserved := COALESCE(v_inventory.reserved_quantity, 0);
  v_new_damaged := COALESCE(v_inventory.damaged_quantity, 0);
  v_new_expired := COALESCE(v_inventory.expired_quantity, 0);

  -- The product's configured base unit, in the order the rest of the system
  -- trusts it: the UOM mapping first, then products.base_unit, then the
  -- legacy text column, and 'pcs' only when a product has no units at all.
  SELECT COALESCE(
           (SELECT u.code
              FROM public.product_uom_mapping m
              JOIN public.uom_master u ON u.id = m.uom_id
             WHERE m.product_id = p.id
               AND m.is_base
               AND COALESCE(m.is_active, true)
             LIMIT 1),
           NULLIF(TRIM(p.base_unit), ''),
           NULLIF(TRIM(p.unit), ''),
           'pcs')
    INTO v_base_unit
  FROM public.products p
  WHERE p.id = p_product_id;

  v_base_unit := COALESCE(v_base_unit, 'pcs');

  -- Resolve product metadata for ledger row (name/unit). An existing row keeps
  -- the unit it already carries; only a new row takes the configured base.
  SELECT COALESCE(v_inventory.product_name, p.name, 'Product'),
         COALESCE(v_inventory.unit, v_base_unit)
    INTO v_product_name, v_product_unit
  FROM public.products p
  WHERE p.id = p_product_id;

  IF v_product_name IS NULL THEN
    v_product_name := COALESCE(v_inventory.product_name, 'Product');
    v_product_unit := COALESCE(v_inventory.unit, v_base_unit);
  END IF;

  IF p_action IN ('OPENING_STOCK', 'GRN') THEN
    IF p_batch_no IS NULL OR TRIM(p_batch_no) = '' THEN
      v_system_batch_code := public.generate_system_batch_code(v_wh_id, p_product_id, CURRENT_DATE);
    ELSE
      v_system_batch_code := TRIM(p_batch_no);
    END IF;
  ELSE
    v_system_batch_code := p_batch_no;
  END IF;

  CASE p_action
    WHEN 'OPENING_STOCK' THEN
      IF v_inventory.id IS NULL THEN
        INSERT INTO public.distributor_inventory (
          distributor_id, product_id, product_name, quantity,
          reserved_quantity, damaged_quantity, expired_quantity,
          unit, batch_number, expiry_date, warehouse_id
        )
        SELECT p_distributor_id, p_product_id, COALESCE(p.name, 'Product'), p_quantity,
               0, 0, 0, v_base_unit, v_system_batch_code, p_expiry_date, v_wh_id
        FROM public.products p WHERE p.id = p_product_id;

        IF NOT FOUND THEN
          INSERT INTO public.distributor_inventory (
            distributor_id, product_id, product_name, quantity,
            reserved_quantity, damaged_quantity, expired_quantity,
            unit, warehouse_id
          ) VALUES (
            p_distributor_id, p_product_id, COALESCE(p_notes, 'Product'), p_quantity,
            0, 0, 0, v_base_unit, v_wh_id
          );
        END IF;

        v_new_quantity := p_quantity;
      ELSE
        v_new_quantity := v_new_quantity + p_quantity;
      END IF;

      INSERT INTO public.inventory_batches (
        distributor_id, product_id, batch_no, system_batch_code, supplier_batch_code,
        mfg_date, expiry_date, quantity, available_qty, warehouse_id
      ) VALUES (
        p_distributor_id, p_product_id, v_system_batch_code, v_system_batch_code, p_supplier_batch_code,
        p_mfg_date, p_expiry_date, p_quantity, p_quantity, v_wh_id
      )
      ON CONFLICT (distributor_id, product_id, batch_no, warehouse_id)
      DO UPDATE SET
        available_qty = public.inventory_batches.available_qty + EXCLUDED.available_qty,
        quantity = public.inventory_batches.quantity + EXCLUDED.quantity,
        supplier_batch_code = COALESCE(EXCLUDED.supplier_batch_code, public.inventory_batches.supplier_batch_code),
        mfg_date = COALESCE(EXCLUDED.mfg_date, public.inventory_batches.mfg_date),
        expiry_date = COALESCE(EXCLUDED.expiry_date, public.inventory_batches.expiry_date)
      RETURNING id INTO v_batch_id;

      v_txn_type := 'OPENING_STOCK';
      v_movement := 'NULL -> Available';
      v_signed_qty := p_quantity;

    WHEN 'GRN' THEN
      IF v_inventory.id IS NULL THEN
        INSERT INTO public.distributor_inventory (
          distributor_id, product_id, product_name, quantity,
          reserved_quantity, damaged_quantity, expired_quantity,
          unit, batch_number, expiry_date, warehouse_id
        )
        SELECT p_distributor_id, p_product_id, COALESCE(p.name, 'Product'), p_quantity,
               0, 0, 0, v_base_unit, v_system_batch_code, p_expiry_date, v_wh_id
        FROM public.products p WHERE p.id = p_product_id;

        IF NOT FOUND THEN
          INSERT INTO public.distributor_inventory (
            distributor_id, product_id, product_name, quantity,
            reserved_quantity, damaged_quantity, expired_quantity,
            unit, warehouse_id
          ) VALUES (
            p_distributor_id, p_product_id, COALESCE(p_notes, 'Product'), p_quantity,
            0, 0, 0, v_base_unit, v_wh_id
          );
        END IF;
        v_new_quantity := p_quantity;
      ELSE
        v_new_quantity := v_new_quantity + p_quantity;
      END IF;

      INSERT INTO public.inventory_batches (
        distributor_id, product_id, batch_no, system_batch_code, supplier_batch_code,
        mfg_date, expiry_date, quantity, available_qty, warehouse_id
      ) VALUES (
        p_distributor_id, p_product_id, v_system_batch_code, v_system_batch_code, p_supplier_batch_code,
        p_mfg_date, p_expiry_date, p_quantity, p_quantity, v_wh_id
      )
      ON CONFLICT (distributor_id, product_id, batch_no, warehouse_id)
      DO UPDATE SET
        available_qty = public.inventory_batches.available_qty + EXCLUDED.available_qty,
        quantity = public.inventory_batches.quantity + EXCLUDED.quantity,
        supplier_batch_code = COALESCE(EXCLUDED.supplier_batch_code, public.inventory_batches.supplier_batch_code),
        mfg_date = COALESCE(EXCLUDED.mfg_date, public.inventory_batches.mfg_date),
        expiry_date = COALESCE(EXCLUDED.expiry_date, public.inventory_batches.expiry_date)
      RETURNING id INTO v_batch_id;

      v_txn_type := 'GRN';
      v_movement := 'Inward -> Available';
      v_signed_qty := p_quantity;

    WHEN 'RESERVE' THEN
      IF v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock to reserve');
      END IF;
      v_new_reserved := v_new_reserved + p_quantity;
      v_txn_type := 'RESERVE';
      v_movement := 'Available -> Reserved';
      v_signed_qty := p_quantity;

    WHEN 'RELEASE' THEN
      IF v_new_reserved < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Cannot release more than reserved quantity');
      END IF;
      v_new_reserved := v_new_reserved - p_quantity;
      v_txn_type := 'RELEASE';
      v_movement := 'Reserved -> Available';
      v_signed_qty := p_quantity;

    WHEN 'MARK_DAMAGED' THEN
      v_new_available := v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired;
      IF v_new_available < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock');
      END IF;
      v_new_damaged := v_new_damaged + p_quantity;
      v_txn_type := 'MARK_DAMAGED';
      v_movement := 'Available -> Damaged';
      v_signed_qty := p_quantity;

    WHEN 'MARK_EXPIRED' THEN
      v_new_available := v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired;
      IF v_new_available < p_quantity THEN
        RETURN jsonb_build_object('success', false, 'error', 'Insufficient available stock');
      END IF;
      v_new_expired := v_new_expired + p_quantity;
      v_txn_type := 'MARK_EXPIRED';
      v_movement := 'Available -> Expired';
      v_signed_qty := p_quantity;

    ELSE
      RETURN jsonb_build_object('success', false, 'error', 'Unknown action: ' || p_action);
  END CASE;

  IF v_inventory.id IS NOT NULL THEN
    UPDATE public.distributor_inventory
    SET quantity = v_new_quantity,
        reserved_quantity = v_new_reserved,
        damaged_quantity = v_new_damaged,
        expired_quantity = v_new_expired,
        updated_at = now()
    WHERE id = v_inventory.id;
  END IF;

  INSERT INTO public.distributor_inventory_transactions (
    distributor_id, product_id, product_name, transaction_type, balance_qty,
    running_balance, unit, notes, created_by, batch_number,
    reference_type, reference_id, reference_number, warehouse_id, expiry_date
  ) VALUES (
    p_distributor_id, p_product_id, v_product_name, v_txn_type, v_signed_qty,
    v_new_quantity, v_product_unit, p_notes, p_created_by, v_system_batch_code,
    NULL, p_reference_id, p_reference_number, v_wh_id, p_expiry_date
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', p_action,
    'quantity', p_quantity,
    'warehouse_id', v_wh_id,
    'system_batch_code', v_system_batch_code,
    'new_total', v_new_quantity,
    'new_available', v_new_quantity - v_new_reserved - v_new_damaged - v_new_expired,
    'new_reserved', v_new_reserved,
    'new_damaged', v_new_damaged,
    'new_expired', v_new_expired
  );
END;
$function$$Q2570$,400), SQLERRM, SQLSTATE); END $R$;
DO $R$ BEGIN EXECUTE $Q2571$-- Correct the inventory rows that execute_stock_action stamped 'pcs' on.
--
-- Twelve BHARATH BEVERAGES rows were created by one opening-stock run on
-- 28 Oct 2026. Every one is a product whose configured base is GRAM, and every
-- one carries unit = 'pcs' because the function wrote that literal rather than
-- reading the configuration. normalise_unit('pcs') is 'piece', so
-- dms_settle_van_day would refuse each of them with unit_mismatch.
--
-- This changes the unit only. The stored quantity is untouched: 50 remains 50
-- base units, and whether 50 grams is what was meant is a separate question
-- that only the person who typed it can answer. Converting the number here
-- would turn a labelling mistake into a stock movement.
--
-- The ledger rows those twelve writes produced also carry 'pcs'. They are left
-- alone: they record what happened, settlement does not read them, and
-- rewriting an audit trail to match a later correction is how a trail stops
-- being worth keeping.
--
-- Out of scope, deliberately: one South Canara row from 23 Apr 2026
-- (KADAK PYALI ADARAK 250G, unit 'grams' against a configured PIECE base).
-- It predates this bug, points the other way, and belongs with the batch-unit
-- audit rather than with this fix.

DO $$
DECLARE
  v_expected CONSTANT integer := 12;
  v_found integer;
  v_updated integer;
BEGIN
  WITH target AS (
    SELECT di.id
    FROM public.distributor_inventory di
    JOIN public.products p ON p.id = di.product_id
    LEFT JOIN public.product_uom_mapping m
           ON m.product_id = p.id AND m.is_base AND COALESCE(m.is_active, true)
    LEFT JOIN public.uom_master u ON u.id = m.uom_id
    WHERE di.unit = 'pcs'
      AND di.created_at::date = DATE '2026-10-28'
      AND public.normalise_unit(COALESCE(u.code, p.base_unit)) = 'gram'
  )
  SELECT count(*) INTO v_found FROM target;

  IF v_found = 0 THEN
    RAISE NOTICE 'Nothing to correct: already applied, or the rows have moved on.';
    RETURN;
  END IF;

  -- A wider match than the twelve reviewed rows means the data is not what was
  -- reviewed. Stop rather than relabel stock nobody has looked at.
  IF v_found > v_expected THEN
    RAISE EXCEPTION
      'Expected at most % rows to correct, found %. Refusing to relabel unreviewed stock.',
      v_expected, v_found;
  END IF;

  WITH target AS (
    SELECT di.id, COALESCE(u.code, p.base_unit) AS configured_base
    FROM public.distributor_inventory di
    JOIN public.products p ON p.id = di.product_id
    LEFT JOIN public.product_uom_mapping m
           ON m.product_id = p.id AND m.is_base AND COALESCE(m.is_active, true)
    LEFT JOIN public.uom_master u ON u.id = m.uom_id
    WHERE di.unit = 'pcs'
      AND di.created_at::date = DATE '2026-10-28'
      AND public.normalise_unit(COALESCE(u.code, p.base_unit)) = 'gram'
  )
  UPDATE public.distributor_inventory di
     SET unit = t.configured_base,
         updated_at = now()
    FROM target t
   WHERE di.id = t.id;

  GET DIAGNOSTICS v_updated = ROW_COUNT;
  RAISE NOTICE 'Corrected % inventory rows from pcs to their configured base unit.', v_updated;
END;
$$$Q2571$; EXCEPTION WHEN duplicate_table OR duplicate_object OR duplicate_column OR duplicate_function OR duplicate_schema THEN NULL; WHEN OTHERS THEN INSERT INTO replay_log.errors(file,stmt,err,state) VALUES ('20261028100100_correct_pcs_units_written_by_opening_stock.sql', left($Q2571$-- Correct the inventory rows that execute_stock_action stamped 'pcs' on.
